import copy

def json_patch(doc, ops):
    if not isinstance(ops, list):
        raise ValueError("ops must be a list")

    current_doc = copy.deepcopy(doc)

    def parse_pointer(ptr):
        if not isinstance(ptr, str):
            raise ValueError("Pointer must be a string")
        if ptr == "":
            return []
        if not ptr.startswith("/"):
            raise ValueError("Pointer must start with '/'")
        tokens = ptr[1:].split("/")
        parsed = []
        for t in tokens:
            res = []
            i = 0
            while i < len(t):
                if t[i] == '~':
                    if i + 1 < len(t):
                        nxt = t[i+1]
                        if nxt == '1':
                            res.append('/')
                            i += 2
                        elif nxt == '0':
                            res.append('~')
                            i += 2
                        else:
                            raise ValueError(f"Invalid escape in token: {t}")
                    else:
                        raise ValueError(f"Invalid escape at end of token: {t}")
                else:
                    res.append(t[i])
                    i += 1
            parsed.append("".join(res))
        return parsed

    def is_canonical_index(token):
        if not token:
            return False
        if not all(c in '0123456789' for c in token):
            return False
        if len(token) > 1 and token[0] == '0':
            return False
        return True

    def get_value(doc, tokens):
        current = doc
        for token in tokens:
            if isinstance(current, dict):
                if token not in current:
                    raise ValueError(f"Key '{token}' not found")
                current = current[token]
            elif isinstance(current, list):
                if not is_canonical_index(token):
                    raise ValueError(f"Invalid list index: '{token}'")
                idx = int(token)
                if idx >= len(current):
                    raise ValueError(f"Index {idx} out of bounds")
                current = current[idx]
            else:
                raise ValueError(f"Cannot index into {type(current).__name__}")
        return current

    def get_parent_and_last(doc, tokens):
        if not tokens:
            return None, None, doc
        parent = doc
        for token in tokens[:-1]:
            if isinstance(parent, dict):
                if token not in parent:
                    raise ValueError(f"Key '{token}' not found")
                parent = parent[token]
            elif isinstance(parent, list):
                if not is_canonical_index(token):
                    raise ValueError(f"Invalid list index: '{token}'")
                idx = int(token)
                if idx >= len(parent):
                    raise ValueError(f"Index {idx} out of bounds")
                parent = parent[idx]
            else:
                raise ValueError(f"Cannot index into {type(parent).__name__}")
        return parent, tokens[-1], doc

    def json_equal(a, b):
        if type(a) is not type(b):
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                if a != b:
                    return False
            else:
                return False
        if isinstance(a, dict):
            if set(a.keys()) != set(b.keys()):
                return False
            return all(json_equal(a[k], b[k]) for k in a)
        if isinstance(a, list):
            if len(a) != len(b):
                return False
            return all(json_equal(x, y) for x, y in zip(a, b))
        return a == b

    def is_proper_prefix(a, b):
        if len(a) > len(b):
            return False
        for i in range(len(a)):
            if a[i] != b[i]:
                return False
        return len(a) < len(b)

