import copy
import re

CANONICAL_INDEX_RE = re.compile(r'^(0|[1-9][0-9]*)$')

def is_canonical_index(token):
    return bool(CANONICAL_INDEX_RE.match(token))

def parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("Pointer must be a string")
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise ValueError("Pointer must start with '/'")
    raw_tokens = pointer.split('/')[1:]
    parsed_tokens = []
    for token in raw_tokens:
        i = 0
        current = []
        while i < len(token):
            if token[i] == '~':
                if i + 1 < len(token):
                    if token[i+1] == '0':
                        current.append('~')
                        i += 2
                    elif token[i+1] == '1':
                        current.append('/')
                        i += 2
                    else:
                        raise ValueError("Invalid escape sequence in pointer")
                else:
                    raise ValueError("Invalid escape sequence in pointer")
            else:
                current.append(token[i])
                i += 1
        parsed_tokens.append(''.join(current))
    return parsed_tokens

def resolve(doc, tokens):
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise ValueError(f"Key not found: {token}")
            current = current[token]
        elif isinstance(current, list):
            if not is_canonical_index(token):
                raise ValueError(f"Invalid index: {token}")
            idx = int(token)
            if idx >= len(current):
                raise ValueError(f"Index out of bounds: {idx}")
            current = current[idx]
        else:
            raise ValueError("Cannot traverse into non-container")
    return current

def json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        if type(a) != type(b):
            return False
    elif type(a) != type(b):
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a == b
        return False
    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(json_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))
    return a == b

def is_proper_prefix(a, b):
    if len(a) >= len(b):
        return False
    return a == b[:len(a)]

