    if not tokens:
        return value
    parent_tokens = tokens[:-1]
    last_token = tokens[-1]
    parent = resolve(doc, parent_tokens)

    if isinstance(parent, dict):
        parent[last_token] = value
    elif isinstance(parent, list):
        if last_token == '-':
            parent.append(value)
        elif is_canonical_index(last_token):
            idx = int(last_token)
            if idx > len(parent):
                raise ValueError("Index out of bounds")
            parent.insert(idx, value)
        else:
            raise ValueError("Invalid index")
    else:
        raise ValueError("Cannot add to non-container")
    return doc

