import datetime
from datetime import timedelta

def _validate_zone(zone):
    if not isinstance(zone, dict):
        raise ValueError("zone must be a dict")
    if "std" not in zone or "dst" not in zone:
        raise ValueError("zone must contain 'std' and 'dst'")

    std = zone["std"]
    if type(std) is not int or not (-900 <= std <= 900):
        raise ValueError("std must be an int in [-900, 900]")

    dst = zone["dst"]
    if dst is not None:
        if not isinstance(dst, dict):
            raise ValueError("dst must be None or a dict")
        save = dst.get("save")
        if type(save) is not int or not (1 <= save <= 180):
            raise ValueError("dst['save'] must be an int in [1, 180]")

        for key in ("start", "end"):
            rule = dst.get(key)
            if not isinstance(rule, (list, tuple)) or len(rule) != 5:
                raise ValueError(f"dst['{key}'] must be a sequence of 5 ints")
            m, wk, wd, h, mi = rule
            if type(m) is not int or not (1 <= m <= 12):
                raise ValueError(f"dst['{key}'][0] month must be 1-12")
            if type(wk) is not int or not (wk == -1 or 1 <= wk <= 4):
                raise ValueError(f"dst['{key}'][1] week must be 1-4 or -1")
            if type(wd) is not int or not (0 <= wd <= 6):
                raise ValueError(f"dst['{key}'][2] weekday must be 0-6")
            if type(h) is not int or not (0 <= h <= 23):
                raise ValueError(f"dst['{key}'][3] hour must be 0-23")
            if type(mi) is not int or not (0 <= mi <= 59):
                raise ValueError(f"dst['{key}'][4] minute must be 0-59")

        if dst["start"][0] == dst["end"][0]:
            raise ValueError("start and end months must differ")

def _rule_to_local_date(month, week, weekday, year):
    first = datetime.date(year, month, 1)
    days_ahead = weekday - first.weekday()
    if days_ahead < 0:
        days_ahead += 7
    first_occ = first + timedelta(days=days_ahead)

    if week == -1:
        if month == 12:
            next_month_first = datetime.date(year + 1, 1, 1)
        else:
            next_month_first = datetime.date(year, month + 1, 1)
        last_day = next_month_first - timedelta(days=1)
        days_back = last_day.weekday() - weekday
        return last_day - timedelta(days=days_back)
    else:
        return first_occ + timedelta(days=(week - 1) * 7)

def _rule_to_utc(month, week, weekday, hour, minute, year, offset):
    d = _rule_to_local_date(month, week, weekday, year)
    local_dt = datetime.datetime(year, month, d, hour, minute)
    utc_dt = local_dt - timedelta(minutes=offset)
    epoch = datetime.datetime(1970, 1, 1)
    return int((utc_dt - epoch).total_seconds() // 60)

def _date_to_minutes(y, mo, d, h, mi):
    dt = datetime.datetime(y, mo, d, h, mi)
    epoch = datetime.datetime(1970, 1, 1)
    return int((dt - epoch).total_seconds() // 60)

def local_to_utc(zone, y, mo, d, h, mi, fold=0):
    _validate_zone(zone)

    if type(y) is not int or not (1970 <= y <= 2100):
        raise ValueError("y must be an int in [1970, 2100]")
    if type(mo) is not int or not (1 <= mo <= 12):
        raise ValueError("mo must be an int in [1, 12]")
    if type(d) is not int:
        raise ValueError("d must be an int")
    try:
        datetime.date(y, mo, d)
    except ValueError:
        raise ValueError("Invalid date")
    if type(h) is not int or not (0 <= h <= 23):
        raise ValueError("h must be an int in [0, 23]")
    if type(mi) is not int or not (0 <= mi <= 59):
        raise ValueError("mi must be an int in [0, 59]")
    if type(fold) is not int or fold not in (0, 1):
        raise ValueError("fold must be 0 or 1")

    std = zone["std"]
    dst = zone["dst"]

    if dst is None:
        return _date_to_minutes(y, mo, d, h, mi) - std

    save = dst["save"]
    start_m, start_wk, start_wd, start_h, start_mi = dst["start"]
    end_m, end_wk, end_wd, end_h, end_mi = dst["end"]

    if start_m < end_m:
        start_utc = _rule_to_utc(start_m, start_wk, start_wd, start_h, start_mi, y, std)
        end_utc = _rule_to_utc(end_m, end_wk, end_wd, end_h, end_mi, y, std + save)
    else:
        start_utc = _rule_to_utc(start_m, start_wk, start_wd, start_h, start_mi, y, std)
        end_utc = _rule_to_utc(end_m, end_wk, end_wd, end_h, end_mi, y + 1, std + save)

    local_mins = _date_to_minutes(y, mo, d, h, mi)
    t_std = local_mins - std
    t_dst = local_mins - (std + save)

    in_dst = lambda u: start_utc <= u < end_utc

    valid_std = not in_dst(t_std)
    valid_dst = in_dst(t_dst)

    if valid_std and valid_dst:
        # Ambiguous: fold=0 -> first occurrence (DST, earlier UTC), fold=1 -> second (STD, later UTC)
        return t_dst if fold == 0 else t_std
    elif valid_std:
        return t_std
    elif valid_dst:
        return t_dst
    else:
        raise ValueError("Wall clock time does not exist (skipped)")

def next_transition(zone, t):
    _validate_zone(zone)

    if zone["dst"] is None:
        return None

    std = zone["std"]
    save = zone["dst"]["save"]
    start_m, start_wk, start_wd, start_h, start_mi = zone["dst"]["start"]
    end_m, end_wk, end_wd, end_h, end_mi = zone["dst"]["end"]

    # Determine starting year to check
    try:
        base = datetime.datetime(1970, 1, 1)
        y_start = (base + timedelta(minutes=t)).year
    except Exception:
        y_start = 1970

    # Check a few years around t to find the next transition
    candidates = []
    for y in range(y_start - 1, y_start + 4):
        if start_m < end_m:
            s_utc = _rule_to_utc(start_m, start_wk, start_wd, start_h, start_mi, y, std)
            e_utc = _rule_to_utc(end_m, end_wk, end_wd, end_h, end_mi, y, std + save)
            candidates.append((s_utc, std + save))
            candidates.append((e_utc, std))
        else:
            s_utc = _rule_to_utc(start_m, start_wk, start_wd, start_h, start_mi, y, std)
            e_utc = _rule_to_utc(end_m, end_wk, end_wd, end_h, end_mi, y + 1, std + save)
            candidates.append((s_utc, std + save))
            candidates.append((e_utc, std))

    # Filter strictly after t and find minimum
    future = [(inst, off) for inst, off in candidates if inst > t]
    if not future:
        return None

    future.sort(key=lambda x: x[0])
    return future[0]

