    dst = zone.get("dst")
    if dst is not None:
        if not isinstance(dst, dict):
            raise ValueError("dst must be None or dict")
        save = dst.get("save")
        if type(save) is not int or not (1 <= save <= 180):
            raise ValueError("save must be int in 1..180")
        for key in ("start", "end"):
            r = dst.get(key)
            if not isinstance(r, (list, tuple)) or len(r) != 5:
                raise ValueError(f"{key} must be sequence of 5 ints")
            m, w, wd, h, mi = r
            if not all(type(x) is int for x in (m, w, wd, h, mi)):
                raise ValueError(f"{key} fields must be ints")
            if not (1 <= m <= 12): raise ValueError(f"{key} month out of range")
            if not (w in (1, 2, 3, 4, -1)): raise ValueError(f"{key} week out of range")
            if not (0 <= wd <= 6): raise ValueError(f"{key} weekday out of range")
            if not (0 <= h <= 23): raise ValueError(f"{key} hour out of range")
            if not (0 <= mi <= 59): raise ValueError(f"{key} minute out of range")
        if dst["start"][0] == dst["end"][0]:
            raise ValueError("start and end months must differ")

def _rule_to_ymd(y, mo, week, wd):
    first = date(y, mo, 1)
    first_wd = first.weekday()
    if week == -1:
        last_day = calendar.monthrange(y, mo)[1]
        last = date(y, mo, last_day)
        offset = (last.weekday() - wd) % 7
        return date(y, mo, last_day - offset)
    else:
        offset = (wd - first_wd) % 7
        day = 1 + offset + (week - 1) * 7
        return date(y, mo, day)

def _to_utc(y, mo, d, h, mi, offset):
    dt = datetime(y, mo, d, h, mi)
    epoch = datetime(1970, 1, 1)
    return int((dt - epoch).total_seconds() / 60) - offset

def _rule_to_utc(y, mo, week, wd, h, mi, offset):
    d = _rule_to_ymd(y, mo, week, wd).day
    return _to_utc(y, mo, d, h, mi, offset)

