    _validate_zone(zone)
    if type(y) is not int or not (1970 <= y <= 2100):
        raise ValueError("y must be int in 1970..2100")
    if type(mo) is not int or not (1 <= mo <= 12):
        raise ValueError("mo must be int in 1..12")
    if type(d) is not int or d < 1:
        raise ValueError("d must be positive int")
    try:
        datetime(y, mo, d)
    except ValueError:
        raise ValueError("invalid date")
    if type(h) is not int or not (0 <= h <= 23):
        raise ValueError("h must be int in 0..23")
    if type(mi) is not int or not (0 <= mi <= 59):
        raise ValueError("mi must be int in 0..59")
    if fold not in (0, 1):
        raise ValueError("fold must be 0 or 1")

    std = zone["std"]
    dst = zone["dst"]
    if dst is None:
        return _to_utc(y, mo, d, h, mi, std)

    save = dst["save"]
    sm, sw, swd, sh, smin = dst["start"]
    em, ew, ewd, eh, emin = dst["end"]

    ts = _rule_to_utc(y, sm, sw, swd, sh, smin, std)
    te = _rule_to_utc(y, em, ew, ewd, eh, emin, std + save)

    t_std = _to_utc(y, mo, d, h, mi, std)
    t_dst = t_std - save

    in_dst_std = ts <= t_std < te
    in_dst_dst = ts <= t_dst < te

    if in_dst_dst and not in_dst_std:
        return t_dst
    elif in_dst_std and not in_dst_dst:
        return t_std
    elif in_dst_dst and in_dst_std:
        return t_dst if fold == 0 else t_std
    elif not in_dst_dst and in_dst_std:
        raise ValueError("wall time does not exist (skipped)")
    else:
        return t_std

def next_transition(zone, t):
    _validate_zone(zone)
    dst = zone["dst"]
    if dst is None:
        return None

    std = zone["std"]
    save = dst["save"]
    sm, sw, swd, sh, smin = dst["start"]
    em, ew, ewd, eh, emin = dst["end"]

    y = 1970
