import datetime

def _days_in_month(y, m):
    if m == 2:
        return 29 if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0) else 28
    return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]

def _date_to_minutes(y, mo, d):
    return (datetime.date(y, mo, d).toordinal() - datetime.date(1970, 1, 1).toordinal()) * 1440

def _validate_zone(zone):
    if not isinstance(zone, dict):
        raise ValueError("zone must be a dict")
    std = zone.get("std")
    if not isinstance(std, int) or not (-900 <= std <= 900):
        raise ValueError("invalid std")
    dst = zone.get("dst")
    if dst is not None:
        if not isinstance(dst, dict):
            raise ValueError("dst must be None or dict")
        save = dst.get("save")
        if not isinstance(save, int) or not (1 <= save <= 180):
            raise ValueError("invalid save")
        for key in ("start", "end"):
            rule = dst.get(key)
            if not isinstance(rule, (list, tuple)) or len(rule) != 5:
                raise ValueError(f"invalid {key}")
            m, w, wd, h, mi = rule
            if not (isinstance(m, int) and 1 <= m <= 12): raise ValueError("invalid month")
            if not (isinstance(w, int) and (1 <= w <= 4 or w == -1)): raise ValueError("invalid week")
            if not (isinstance(wd, int) and 0 <= wd <= 6): raise ValueError("invalid weekday")
            if not (isinstance(h, int) and 0 <= h <= 23): raise ValueError("invalid hour")
            if not (isinstance(mi, int) and 0 <= mi <= 59): raise ValueError("invalid minute")
        if dst["start"][0] == dst["end"][0]:
            raise ValueError("start and end months must differ")
    return std, dst

def _compute_transitions(y, std, dst):
    save = dst["save"]
    sm, sw, sd, sh, smi = dst["start"]
    em, ew, ed, eh, emi = dst["end"]
    is_north = sm < em

    def _rule_day(yr, m, w, wd):
        first_wd = datetime.date(yr, m, 1).weekday()
        diff = (wd - first_wd) % 7
        if w == -1:
            last_d = _days_in_month(yr, m)
            last_wd = datetime.date(yr, m, last_d).weekday()
            diff = (wd - last_wd) % 7
            return last_d - diff
        return 1 + diff + (w - 1) * 7

    start_d = _rule_day(y, sm, sw, sd)
    end_y = y if is_north else y + 1
    end_d = _rule_day(end_y, em, ew, ed)

    utc_start = _date_to_minutes(y, sm, start_d) + sh * 60 + smi - std
    utc_end = _date_to_minutes(end_y, em, end_d) + eh * 60 + emi - (std + save)
    return utc_start, utc_end, is_north

def local_to_utc(zone, y, mo, d, h, mi, fold=0):
    std, dst = _validate_zone(zone)
    if not (1970 <= y <= 2100):
        raise ValueError("year out of range")
    if not (isinstance(mo, int) and 1 <= mo <= 12):
        raise ValueError("invalid month")
    if not (isinstance(d, int) and 1 <= d <= _days_in_month(y, mo)):
        raise ValueError("invalid day")
    if not (isinstance(h, int) and 0 <= h <= 23):
        raise ValueError("invalid hour")
    if not (isinstance(mi, int) and 0 <= mi <= 59):
        raise ValueError("invalid minute")
    if not (isinstance(fold, int) and fold in (0, 1)):
        raise ValueError("fold must be 0 or 1")

    L = _date_to_minutes(y, mo, d) + h * 60 + mi
    if dst is None:
        return L - std

    utc_start, utc_end, is_north = _compute_transitions(y, std, dst)

    # Check for non-existent times (spring forward gap)
    if utc_start < L - std < utc_start + save:
        raise ValueError("wall time does not exist")

    utc_std = L - std
    utc_dst = utc_std - save

    # Determine if the time falls in the DST interval
    in_dst = utc_dst >= utc_start
    if is_north:
