        parsed_jobs.append({
            'index': i,
            'arrival': arrival,
            'burst': burst,
            'priority': priority,
            'rem_burst': burst,
            'start_time': None
        })

    # Sort by arrival time, then by original index to preserve input order for ties
    pending = sorted(parsed_jobs, key=lambda x: (x['arrival'], x['index']))

