            if results[running_job['index']] is None:
                results[running_job['index']] = (running_job['start_time'], current_time)
            else:
                results[running_job['index']] = (results[running_job['index']][0], current_time)
            completed_count += 1
            running_job = None
            rem_quantum = 0
            # CPU is free

        # Phase 3: Check Quantum Expiry and Preemption
        if running_job is not None:
