                rem_quantum = 0
            else:
                # Check Preemption: strictly better priority waiting
                # We need to check if any queue has a priority < running_job['priority']
                # Optimization: track min priority in queues?
                # Since N is small, linear scan is fine.
                min_waiting_p = min(queues.keys()) if queues else float('inf')
                if min_waiting_p < running_job['priority']:
                    # Preemption: goes to FRONT of queue
                    queues[running_job['priority']].appendleft(running_job)
                    running_job = None
                    rem_quantum = 0

        # Phase 4: Select New Job
        if running_job is None:
            next_job = get_best_job()
            if next_job is not None:
                running_job = next_job
                rem_quantum = q
                if results[running_job['index']] is None:
                    results[running_job['index']] = (current_time, None)
                # Start time is already recorded if first run
            else:
                # CPU idle, wait for next arrival
                if pending:
                    current_time = pending[0]['arrival']
                    continue
                else:
                    # Should not happen if completed_count < len(jobs)
                    break

        # Phase 5: Advance Time
        if running_job is not None:
            # Determine duration to run
            # Constraints: rem_burst, rem_quantum, next arrival that preempts
            duration = min(running_job['rem_burst'], rem_quantum)

            # Check if a better job arrives before duration ends
            if pending:
