                        duration = next_arrival_time - current_time

            if duration > 0:
                current_time += duration
                running_job['rem_burst'] -= duration
                rem_quantum -= duration
            else:
                # Should not happen if logic is correct, but safety break
                current_time += 1
                if running_job['rem_burst'] > 0:
