    indexed_jobs = [(i, job) for i, job in enumerate(jobs)]
    sorted_jobs = sorted(indexed_jobs, key=lambda x: x[1][0])

    queues = defaultdict(deque)
    running = None
    t = 0
    job_ptr = 0
    n = len(sorted_jobs)
    results = [None] * n

    # Helper to check if any queue has jobs
    def any_queue_has_jobs():
        return any(len(d) > 0 for d in queues.values())

    while job_ptr < n or running is not None or any_queue_has_jobs():
        # Determine next event time
        next_t = t

        if running is None:
            if job_ptr < n:
                next_t = min(next_t, sorted_jobs[job_ptr][1][0])
        else:
            # Running job events
            quantum_end = running.quantum_start + q
            completion_end = running.quantum_start + running.remaining
            next_t = min(next_t, quantum_end, completion_end)
            if job_ptr < n:
                next_t = min(next_t, sorted_jobs[job_ptr][1][0])

        t = next_t

        # 1. Check completion
        if running is not None and running.remaining == 0:
            results[running.idx] = (running.start, t)
            running = None

        # 2. Process arrivals
        while job_ptr < n and sorted_jobs[job_ptr][1][0] == t:
            idx, (arr, burst, pri) = sorted_jobs[job_ptr]
            queues[pri].append(idx)
            job_ptr += 1

