            quantum_expired = (t - running.quantum_start >= q)
            # Check for strictly better priority waiting
            has_better = any(len(queues[p]) > 0 for p in queues if p < running.priority)

            if quantum_expired:
                queues[running.priority].append(running.idx) # BACK
                running = None
            elif has_better:
                queues[running.priority].appendleft(running.idx) # FRONT
                running = None

        # 4. Scheduling
