            best_p = None
            # Find smallest priority number with non-empty queue
            for p in sorted(queues.keys()):
                if queues[p]:
                    best_p = p
                    break
            if best_p is not None:
                idx = queues[best_p].popleft()
                arr, burst, pri = jobs[idx]
                running = RunningJob(idx=idx, remaining=burst, start=t, quantum_start=t, priority=pri)

    return results

