            running = None

        # 2. Arrivals
        while arr_idx < n and indexed_jobs[arr_idx][0] == t:
            _, i, b, p = indexed_jobs[arr_idx]
            job_data[i] = (b, p)
            queues[p].append(i)
            arr_idx += 1

        # 3. Preemption / Quantum
        if running is not None:
            if running['q_used'] == q:
                queues[running['pri']].append(running['idx'])
                running = None
            else:
                has_better = False
                for p in queues:
                    if queues[p] and p < running['pri']:
                        has_better = True
                        break
                if has_better:
                    queues[running['pri']].appendleft(running['idx'])
                    running = None

        # 4. Start job
        if running is None:
            best_p = None
            for p in queues:
                if queues[p]:
                    if best_p is None or p < best_p:
                        best_p = p
            if best_p is not None:
                i = queues[best_p].popleft()
                b, p = job_data[i]
                running = {'idx': i, 'rem': b, 'pri': p, 'start': t, 'q_used': 0}

        # Calculate next event time
        if running is not None and running['rem'] > 0:
            next_t = min(t + running['rem'], t + q)
            for k in range(arr_idx, n):
                at, _, _, ap = indexed_jobs[k]
                if at > t:
                    if ap < running['pri']:
                        next_t = min(next_t, at)
                    break
        else:
            next_t = indexed_jobs[arr_idx][0] if arr_idx < n else float('inf')

        current_time = next_t
        if current_time == float('inf'):
            break
        current_time = int(current_time)

    if running is not None:
        results[running['idx']] = (running['start'], current_time)

    return results

