        # add: Int -> Int -> Int
        self.env.append(("add", (self._func(self._int, self._func(self._int, self._int)), frozenset())))
        # eq: a -> a -> Bool
        a = self.fresh_counter; self.fresh_counter += 1
        self.env.append(("eq", (self._func(self._tv(a), self._func(self._tv(a), self._bool)), frozenset({a}))))
        # not: Bool -> Bool
        self.env.append(("not", (self._func(self._bool, self._bool), frozenset())))

    def _int(self): return ("Int",)
    def _bool(self): return ("Bool",)
    def _tv(self, i): return ("tv", i)
    def _func(self, a, b): return ("->", a, b)
    def _pair(self, a, b): return ("pair", a, b)

    def fresh(self):
        v = self.fresh_counter
        self.fresh_counter += 1
        return self._tv(v)

    def apply_sub(self, t):
        if t[0] == "tv":
            return self.sub.get(t[1], t)
        if len(t) > 1:
            return tuple(self.apply_sub(c) for c in t[1:])
        return t

    def occurs(self, vid, t):
        t = self.apply_sub(t)
        if t[0] == "tv" and t[1] == vid:
            return True
        if len(t) > 1:
            return any(self.occurs(vid, c) for c in t[1:])
        return False

    def unify(self, t1, t2):
        t1 = self.apply_sub(t1)
        t2 = self.apply_sub(t2)
        if t1 == t2:
            return
        if t1[0] == "tv":
            if self.occurs(t1[1], t2):
                raise ValueError("Infinite type")
            self.sub[t1[1]] = t2
            return
        if t2[0] == "tv":
            if self.occurs(t2[1], t1):
                raise ValueError("Infinite type")
            self.sub[t2[1]] = t1
            return
        if t1[0] != t2[0] or t1[0] in ("Int", "Bool"):
            raise ValueError("Type mismatch")
        if len(t1) != len(t2):
            raise ValueError("Type mismatch")
        for a, b in zip(t1, t2):
            self.unify(a, b)

    def free_vars(self, t):
        if t[0] == "tv":
            return frozenset({t[1]})
        if len(t) > 1:
            res = frozenset()
            for c in t[1:]:
                res = res | self.free_vars(c)
            return res
        return frozenset()

    def gen(self, t):
        env_vars = frozenset()
        for _, (tau, bound) in self.env:
            env_vars = env_vars | self.free_vars(tau)
        fvs = self.free_vars(t)
        bound = fvs - env_vars
        return (t, bound)

    def inst(self, scheme):
        tau, bound = scheme
        sub = {vid: self.fresh() for vid in bound}
        res = tau
        for vid in bound:
            res = self._apply_dict_sub(res, sub)
        return res

    def _apply_dict_sub(self, t, sub):
        if t[0] == "tv" and t[1] in sub:
            return sub[t[1]]
        if len(t) > 1:
            return tuple(self._apply_dict_sub(c, sub) for c in t[1:])
        return t

    def lookup(self, name):
        for n, scheme in reversed(self.env):
            if n == name:
                return scheme
        raise ValueError("Unbound variable")

    def validate(self, term):
        if not isinstance(term, tuple):
            raise ValueError("Malformed term")
        tag = term[0]
        if tag == "int":
            if len(term) != 2 or not isinstance(term[1], int):
                raise ValueError("Malformed term")
        elif tag == "bool":
            if len(term) != 2 or not isinstance(term[1], bool):
                raise ValueError("Malformed term")
        elif tag == "var":
            if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed term")
            self.validate(term[1]) # name is str, already checked
        elif tag == "lam":
            if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed term")
            self.validate(term[2])
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Malformed term")
            self.validate(term[1])
            self.validate(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Malformed term")
            self.validate(term[1])
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "pair":
            if len(term) != 3:
                raise ValueError("Malformed term")
            self.validate(term[1])
            self.validate(term[2])
        elif tag == "fst" or tag == "snd":
            if len(term) != 2:
                raise ValueError("Malformed term")
            self.validate(term[1])
        elif tag == "let":
            if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed term")
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "letrec":
            if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed term")
            self.validate(term[2])
            self.validate(term[3])
        else:
            raise ValueError("Unknown tag")

    def infer_term(self, term):
        self.validate(term)
        tag = term[0]
        if tag == "int":
            return self._int()
        elif tag == "bool":
            return self._bool()
        elif tag == "var":
            tau, _ = self.lookup(term[1])
            return self.inst((tau, frozenset()))
        elif tag == "lam":
            name = term[1]
            body = term[2]
            fresh_v = self.fresh()
            self.env.append((name, (fresh_v, frozenset())))
            tau_body = self.infer_term(body)
            self.env.pop()
            return self._func(fresh_v, tau_body)
        elif tag == "app":
            tau_f = self.infer_term(term[1])
            tau_arg = self.infer_term(term[2])
            res_t = self.fresh()
            self.unify(tau_f, self._func(tau_arg, res_t))
            return self.apply_sub(res_t)
        elif tag == "if":
            tau_c = self.infer_term(term[1])
            self.unify(tau_c, self._bool())
            tau_t = self.infer_term(term[2])
            tau_e = self.infer_term(term[3])
            self.unify(tau_t, tau_e)
            return self.apply_sub(tau_t)
        elif tag == "pair":
            tau_a = self.infer_term(term[1])
            tau_b = self.infer_term(term[2])
            return self._pair(tau_a, tau_b)
        elif tag == "fst":
            tau_e = self.infer_term(term[1])
            p1, p2 = self.fresh(), self.fresh()
            self.unify(tau_e, self._pair(p1, p2))
            return self.apply_sub(p1)
        elif tag == "snd":
            tau_e = self.infer_term(term[1])
            p1, p2 = self.fresh(), self.fresh()
            self.unify(tau_e, self._pair(p1, p2))
            return self.apply_sub(p2)
        elif tag == "let":
            name = term[1]
            e1, e2 = term[2], term[3]
            tau1 = self.infer_term(e1)
            scheme = self.gen(tau1)
            self.env.append((name, scheme))
            tau2 = self.infer_term(e2)
            self.env.pop()
            return self.apply_sub(tau2)
        elif tag == "letrec":
            name = term[1]
            e1, e2 = term[2], term[3]
            fresh_v = self.fresh()
            self.env.append((name, (fresh_v, frozenset())))
            tau1 = self.infer_term(e1)
            scheme = self.gen(tau1)
            self.env[-1] = (name, scheme)
            tau2 = self.infer_term(e2)
            self.env.pop()
            return self.apply_sub(tau2)
        else:
            raise ValueError("Unknown tag")

    def print_type(self, t, names):
        if t[0] == "Int": return "Int"
        if t[0] == "Bool": return "Bool"
        if t[0] == "tv": return names[t[1]]
        if t[0] == "->":
            left = self.print_type(t[1], names)
            right = self.print_type(t[2], names)
            if t[1][0] == "->":
                left = f"({left})"
            return f"{left} -> {right}"
        if t[0] == "pair":
            return f"({self.print_type(t[1], names)}, {self.print_type(t[2], names)})"
        return str(t)

    def collect_vars(self, t, seen):
        if t[0] == "tv":
            if t[1] not in seen:
                seen.add(t[1])
                return [t[1]]
            return []
        if len(t) > 1:
            return self.collect_vars(t[1], seen) + self.collect_vars(t[2], seen)
        return []

    def name_gen(self):
        for i in range(26):
            yield chr(ord('a') + i)
        i = 0
        while True:
            for j in range(26):
                yield f"{chr(ord('a') + j)}{i + 1}"
            i += 1

