    inf = HMInference()
    tau = inf.infer_term(term)
    tau = inf.apply_sub(tau)
    seen = set()
    vids = inf.collect_vars(tau, seen)
    names = {vid: name for vid, name in zip(vids, inf.name_gen())}
    return inf.print_type(tau, names)

