class HMInference:
    def __init__(self):
        self.sub = {}
        self.fresh_counter = 0
        self.env = []
        self._init_env()

    def _init_env(self):
        # add: Int -> Int -> Int
        self.env.append(("add", (self._func(self._int(), self._func(self._int(), self._int())), frozenset())))
        # eq: a -> a -> Bool
        a = self.fresh_counter; self.fresh_counter += 1
        self.env.append(("eq", (self._func(self._tv(a), self._func(self._tv(a), self._bool())), frozenset({a}))))
        # not: Bool -> Bool
        self.env.append(("not", (self._func(self._bool(), self._bool()), frozenset())))

    def _int(self): return ("Int",)
    def _bool(self): return ("Bool",)
    def _tv(self, i): return ("tv", i)
    def _func(self, a, b): return ("->", a, b)
    def _pair(self, a, b): return ("pair", a, b)

    def fresh(self):
        v = self.fresh_counter
        self.fresh_counter += 1
        return self._tv(v)

    def apply_sub(self, t):
        if t[0] == "tv":
            return self.sub.get(t[1], t)
        if len(t) > 1:
            return tuple(self.apply_sub(c) for c in t[1:])
        return t

    def occurs(self, vid, t):
        t = self.apply_sub(t)
        if t[0] == "tv" and t[1] == vid:
            return True
        if len(t) > 1:
            return any(self.occurs(vid, c) for c in t[1:])
        return False

    def unify(self, t1, t2):
        t1 = self.apply_sub(t1)
        t2 = self.apply_sub(t2)
        if t1 == t2:
            return
        if t1[0] == "tv":
            if self.occurs(t1[1], t2):
                raise ValueError("Infinite type")
            self.sub[t1[1]] = t2
            return
        if t2[0] == "tv":
            if self.occurs(t2[1], t1):
                raise ValueError("Infinite type")
            self.sub[t2[1]] = t1
            return
        if t1[0] != t2[0] or t1[0] in ("Int", "Bool"):
            raise ValueError("Type mismatch")
        if len(t1) != len(t2):
            raise ValueError("Type mismatch")
        for a, b in zip(t1, t2):
            self.unify(a, b)

    def free_vars(self, t):
        if t[0] == "tv":
            return frozenset({t[1]})
        if len(t) > 1:
            res = frozenset()
            for c in t[1:]:
                res = res | self.free_vars(c)
            return res
        return frozenset()

    def gen(self, t):
        env_vars = frozenset()
        for _, (tau, bound) in self.env:
            env_vars = env_vars | (self.free_vars(tau) - bound)
        fvs = self.free_vars(t)
        bound = fvs - env_vars
        return (t, bound)

