            unify(te, ("Pair", xs, ys))
            return xs
        if t[0] == "snd":
            e = t[1]
            te = infer_term(e, env)
            xs = fresh(); ys = fresh()
            unify(te, ("Pair", xs, ys))
            return ys
        if t[0] == "let":
            name, e1, e2 = t[1], t[2], t[3]
            t1 = infer_term(e1, env)
            new_env = env | {name: t1}
            return infer_term(e2, new_env)
        if t[0] == "letrec":
            name, e1, e2 = t[1], t[2], t[3]
            x = fresh()
            new_env = env | {name: x}
            t1 = infer_term(e1, new_env)
            new_env2 = env | {name: t1}
