    chars = "abcdefghijklmnopqrstuvwxyz"

    def get_name(v):
        if v not in names:
            i = idx[0]
            if i < 26:
                names[v] = chars[i]
            else:
                group = (i - 26) // 26
                char_i = (i - 26) % 26
                names[v] = chars[char_i] + str(group + 1)
            idx[0] += 1
        return names[v]

    def to_str(t):
        if t[0] == "Var":
            return get_name(t[1])
        if t[0] == "Int":
            return "Int"
        if t[0] == "Bool":
