        elif tag == "fst":
            if len(t) != 2: raise ValueError("malformed term")
            validate(t[1])
        elif tag == "snd":
            if len(t) != 2: raise ValueError("malformed term")
            validate(t[1])
        elif tag == "let":
            if len(t) != 4: raise ValueError("malformed term")
            if not isinstance(t[1], str) or not t[1]: raise ValueError("malformed term")
            validate(t[2]); validate(t[3])
        elif tag == "letrec":
            if len(t) != 4: raise ValueError("malformed term")
            if not isinstance(t[1], str) or not t[1]: raise ValueError("malformed term")
            validate(t[2]); validate(t[3])
        else:
            raise ValueError("malformed term")

    validate(term)

    counter = [0]
    subs = {}

    def fresh():
        v = ("Var", counter[0])
        counter[0] += 1
        return v

    def apply_subs(t):
        if t[0] == "Var":
            if t[1] in subs:
                return apply_subs(subs[t[1]])
            return t
        if t[0] in ("Func", "Pair"):
            return (t[0], apply_subs(t[1]), apply_subs(t[2]))
        return t

    def occurs(v, t):
        if t[0] == "Var" and t[1] == v: return True
        if t[0] in ("Func", "Pair"):
            return occurs(v, t[1]) or occurs(v, t[2])
        return False

    def unify(t1, t2):
        t1 = apply_subs(t1)
        t2 = apply_subs(t2)
        if t1 == t2: return
        if t1[0] == "Var":
            if occurs(t1[1], t2): raise ValueError("infinite type")
            subs[t1[1]] = t2
        elif t2[0] == "Var":
            if occurs(t2[1], t1): raise ValueError("infinite type")
            subs[t2[1]] = t1
        elif t1[0] != t2[0]:
            raise ValueError("type mismatch")
        elif t1[0] in ("Func", "Pair"):
            unify(t1[1], t2[1])
            unify(t1[2], t2[2])
        else:
            raise ValueError("type mismatch")

    def inst(t, rigid):
        if t[0] == "Var":
            if t[1] in rigid:
                return t
            return fresh()
        if t[0] in ("Func", "Pair"):
            return (t[0], inst(t[1], rigid), inst(t[2], rigid))
        return t

    def free_vars(t):
        if t[0] == "Var": return {t[1]}
        if t[0] in ("Func", "Pair"): return free_vars(t[1]) | free_vars(t[2])
        return set()

    def infer_term(t, env, rigid):
        if t[0] == "int":
            return ("Int",)
        if t[0] == "bool":
            return ("Bool",)
        if t[0] == "var":
            name = t[1]
            if name not in env: raise ValueError("unbound variable")
            return inst(env[name], rigid)
        if t[0] == "lam":
            name, body = t[1], t[2]
            x = fresh()
            new_rigid = rigid | {x}
            new_env = env | {name: x}
            res = infer_term(body, new_env, new_rigid)
            return ("Func", x, res)
        if t[0] == "app":
            f, arg = t[1], t[2]
            tf = infer_term(f, env, rigid)
            ta = infer_term(arg, env, rigid)
            xr = fresh()
            unify(tf, ("Func", ta, xr))
            return xr
        if t[0] == "if":
            c, tb, te = t[1], t[2], t[3]
            unify(infer_term(c, env, rigid), ("Bool",))
            bt = infer_term(tb, env, rigid)
            et = infer_term(te, env, rigid)
            unify(bt, et)
            return bt
        if t[0] == "pair":
            a, b = t[1], t[2]
            ta = infer_term(a, env, rigid)
            tb = infer_term(b, env, rigid)
            return ("Pair", ta, tb)
        if t[0] == "fst":
            e = t[1]
            te = infer_term(e, env, rigid)
            xs = fresh(); ys = fresh()
            unify(te, ("Pair", xs, ys))
            return xs
        if t[0] == "snd":
            e = t[1]
            te = infer_term(e, env, rigid)
            xs = fresh(); ys = fresh()
            unify(te, ("Pair", xs, ys))
            return ys
        if t[0] == "let":
            name, e1, e2 = t[1], t[2], t[3]
            t1 = infer_term(e1, env, rigid)
            new_env = env | {name: t1}
            return infer_term(e2, new_env, rigid)
        if t[0] == "letrec":
            name, e1, e2 = t[1], t[2], t[3]
            x = fresh()
            new_rigid = rigid | {x}
            new_env = env | {name: x}
            t1 = infer_term(e1, new_env, new_rigid)
            new_env2 = env | {name: t1}
            return infer_term(e2, new_env2, rigid)

    v_eq = fresh()
    env = {
        "add": ("Func", ("Int",), ("Func", ("Int",), ("Int",))),
        "eq": ("Func", ("Var", v_eq), ("Func", ("Var", v_eq), ("Bool",))),
        "not": ("Func", ("Bool",), ("Bool",))
    }

    final_type = infer_term(term, env, set())
    final_type = apply_subs(final_type)

    # Formatting
    names = {}
    idx = [0]
    chars = "abcdefghijklmnopqrstuvwxyz"

    def get_name(v):
        if v not in names:
            i = idx[0]
            if i < 26:
                names[v] = chars[i]
            else:
                group = (i - 26) // 26
                char_i = (i - 26) % 26
                names[v] = chars[char_i] + str(group + 1)
            idx[0] += 1
        return names[v]

    def to_str(t):
        if t[0] == "Var":
            return get_name(t[1])
        if t[0] == "Int":
            return "Int"
        if t[0] == "Bool":
            return "Bool"
        if t[0] == "Func":
            s1 = to_str(t[1])
            s2 = to_str(t[2])
            if t[1][0] == "Func":
                s1 = f"({s1})"
            return f"{s1} -> {s2}"
        if t[0] == "Pair":
            s1 = to_str(t[1])
            s2 = to_str(t[2])
            return f"({s1}, {s2})"
        return ""

    return to_str(final_type)

def infer(term):
    # Validate term structure
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    valid_tags = {'int', 'bool', 'var', 'lam', 'app', 'if', 'pair', 'fst', 'snd', 'let', 'letrec'}
    if tag not in valid_tags:
        raise ValueError("Malformed term")

    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int): raise ValueError("Malformed term")
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed term")
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
    elif tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
    elif tag == 'app':
        if len(term) != 3: raise ValueError("Malformed term")
    elif tag == 'if':
        if len(term) != 4: raise ValueError("Malformed term")
    elif tag == 'pair':
        if len(term) != 3: raise ValueError("Malformed term")
    elif tag == 'fst':
        if len(term) != 2: raise ValueError("Malformed term")
    elif tag == 'snd':
        if len(term) != 2: raise ValueError("Malformed term")
    elif tag == 'let':
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
    elif tag == 'letrec':
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")

    # Initial environment
    ctx = {
        'add': ('Fun', ('Fun', ('Int',), ('Int',)), ('Int',)),
        'eq': ('Fun', ('Fun', ('Var', 'a'), ('Bool',))),
        'not': ('Fun', ('Bool',), ('Bool',))
    }
    sub = {}
    fresh_id = [0]

    def fresh_var():
        idx = fresh_id[0]
        fresh_id[0] += 1
        return f'v{idx}'

    def apply_sub(t, s):
        if t[0] == 'Var':
            return s.get(t[1], t)
        return (t[0], *(apply_sub(a, s) for a in t[1:]))

    def free_vars(t):
        if t[0] == 'Var': return {t[1]}
        return set().union(*(free_vars(a) for a in t[1:]))

    def occurs_check(v, t):
        if t[0] == 'Var': return t[1] == v
        return any(occurs_check(v, a) for a in t[1:])

    def unify(t1, t2, s):
        t1 = apply_sub(t1, s)
        t2 = apply_sub(t2, s)
        if t1 == t2: return s
        v1 = t1[0] == 'Var'
        v2 = t2[0] == 'Var'
        if v1 and v2:
            if t1[1] not in s:
                return {**s, t1[1]: t2}
            elif t2[1] not in s:
                return {**s, t2[1]: t1}
            else:
                raise ValueError("Type mismatch")
        if v1:
            if occurs_check(t1[1], t2):
                raise ValueError("Occurs check failed")
            return {**s, t1[1]: t2}
        if v2:
            if occurs_check(t2[1], t1):
                raise ValueError("Occurs check failed")
            return {**s, t2[1]: t1}
        if t1[0] != t2[0]:
            raise ValueError("Type mismatch")
        if t1[0] in ('Fun', 'Pair'):
            s1 = unify(t1[1], t2[1], s)
            return unify(t1[2], t2[2], s1)
        raise ValueError("Type mismatch")

    def free_ctx():
        res = set()
        for t in ctx.values():
            res.update(free_vars(t))
        return res

    def infer_term(term, ctx, sub):
        tag = term[0]
        if tag == 'int':
            return ('Int',), sub
        elif tag == 'bool':
            return ('Bool',), sub
        elif tag == 'var':
            name = term[1]
            if name not in ctx:
                raise ValueError("Unbound variable")
            t = ctx[name]
            free = free_vars(t)
            inst_sub = {v: ('Var', fresh_var()) for v in free}
            t_inst = apply_sub(t, inst_sub)
            return apply_sub(t_inst, sub), sub
        elif tag == 'lam':
            name = term[1]
            body = term[2]
            t_name = ('Var', fresh_var())
            new_ctx = {**ctx, name: t_name}
            return infer_term(body, new_ctx, sub)
        elif tag == 'app':
            f_term, arg_term = term[1], term[2]
            t_f, sub1 = infer_term(f_term, ctx, sub)
            t_arg, sub2 = infer_term(arg_term, ctx, sub1)
            res_t = ('Var', fresh_var())
            t_f_unified = apply_sub(t_f, sub2)
            t_arg_unified = apply_sub(t_arg, sub2)
            sub3 = unify(t_f_unified, ('Fun', t_arg_unified, res_t), sub2)
            return res_t, sub3
        elif tag == 'if':
            c, t, e = term[1], term[2], term[3]
            t_c, sub1 = infer_term(c, ctx, sub)
            t_t, sub2 = infer_term(t, ctx, sub1)
            t_e, sub3 = infer_term(e, ctx, sub2)
            sub4 = unify(t_c, ('Bool',), sub3)
            sub5 = unify(t_t, t_e, sub4)
            return t_t, sub5
        elif tag == 'pair':
            a, b = term[1], term[2]
            t_a, sub1 = infer_term(a, ctx, sub)
            t_b, sub2 = infer_term(b, ctx, sub1)
            return ('Pair', t_a, t_b), sub2
        elif tag == 'fst':
            e = term[1]
            t_e, sub1 = infer_term(e, ctx, sub)
            t1, t2 = ('Var', fresh_var()), ('Var', fresh_var())
            sub2 = unify(t_e, ('Pair', t1, t2), sub1)
            return t1, sub2
        elif tag == 'snd':
            e = term[1]
            t_e, sub1 = infer_term(e, ctx, sub)
            t1, t2 = ('Var', fresh_var()), ('Var', fresh_var())
            sub2 = unify(t_e, ('Pair', t1, t2), sub1)
            return t2, sub2
        elif tag == 'let':
            name, e1, e2 = term[1], term[2], term[3]
            t_e1, sub1 = infer_term(e1, ctx, sub)
            free_env = free_ctx()
            quantified = free_vars(t_e1) - free_env
            inst_sub = {v: ('Var', fresh_var()) for v in quantified}
            ctx[name] = apply_sub(t_e1, inst_sub)
            t_e2, sub2 = infer_term(e2, ctx, sub1)
            return t_e2, sub2
        elif tag == 'letrec':
            name, e1, e2 = term[1], term[2], term[3]
            t_name = ('Var', fresh_var())
            ctx[name] = t_name
            t_e1, sub1 = infer_term(e1, ctx, sub)
            free_env = free_ctx()
            quantified = free_vars(t_e1) - free_env
            inst_sub = {v: ('Var', fresh_var()) for v in quantified}
            ctx[name] = apply_sub(t_e1, inst_sub)
            t_e2, sub2 = infer_term(e2, ctx, sub1)
            return t_e2, sub2
        raise ValueError("Malformed term")

    final_type, _ = infer_term(term, ctx, sub)

    # Collect variables in order of first appearance
    seen = []
    def collect_vars(t):
        if t[0] == 'Var':
            if t[1] not in seen:
                seen.append(t[1])
        else:
            for a in t[1:]:
                collect_vars(a)
    collect_vars(final_type)

    # Map to required naming scheme
    var_map = {}
    for i, v in enumerate(seen):
        group = i // 26
        char = chr(ord('a') + i % 26)
        var_map[v] = f"{char}{group}" if group > 0 else char

    def replace_and_format(t):
        if t[0] == 'Var':
            return var_map[t[1]]
        if t[0] == 'Int': return 'Int'
        if t[0] == 'Bool': return 'Bool'
        if t[0] == 'Fun':
            a = replace_and_format(t[1])
            b = replace_and_format(t[2])
            if t[1][0] == 'Fun':
                a = f"({a})"
            return f"{a} -> {b}"
        if t[0] == 'Pair':
            return f"({replace_and_format(t[1])}, {replace_and_format(t[2])})"
        return str(t)

    return replace_and_format(final_type)

import sys

class Type: pass
class Int(Type): pass
class Bool(Type): pass
class Var(Type):
    def __init__(self, i): self.i = i
class Fun(Type):
    def __init__(self, a, b): self.a = a; self.b = b
class Pair(Type):
    def __init__(self, a, b): self.a = a; self.b = b

_fresh_counter = 0
def fresh():
    global _fresh_counter
    v = Var(_fresh_counter)
    _fresh_counter += 1
    return v

def free_vars(t):
    if isinstance(t, Var): return {t}
    if isinstance(t, Fun): return free_vars(t.a) | free_vars(t.b)
    if isinstance(t, Pair): return free_vars(t.a) | free_vars(t.b)
    return set()

def apply(t, s):
    if isinstance(t, Var): return s.get(t, t)
    if isinstance(t, Fun): return Fun(apply(t.a, s), apply(t.b, s))
    if isinstance(t, Pair): return Pair(apply(t.a, s), apply(t.b, s))
    return t

def occurs(v, t):
    if t == v: return True
    if isinstance(t, Fun): return occurs(v, t.a) or occurs(v, t.b)
    if isinstance(t, Pair): return occurs(v, t.a) or occurs(v, t.b)
    return False

def unify(t1, t2, s):
    t1 = apply(t1, s)
    t2 = apply(t2, s)
    if t1 == t2: return s
    if isinstance(t1, Var):
        if occurs(t1, t2): raise ValueError("Occurs check")
        return {t1: t2} | s
    if isinstance(t2, Var):
        if occurs(t2, t1): raise ValueError("Occurs check")
        return {t2: t1} | s
    if isinstance(t1, Fun) and isinstance(t2, Fun):
        s = unify(t1.a, t2.a, s)
        return unify(t1.b, t2.b, s)
    if isinstance(t1, Pair) and isinstance(t2, Pair):
        s = unify(t1.a, t2.a, s)
        return unify(t1.b, t2.b, s)
    raise ValueError("Type mismatch")

def free_vars_env(env):
    res = set()
    for scope in env:
        for _, val in scope.items():
            if isinstance(val, tuple) and val[0] == "poly":
                res |= free_vars(val[1])
            else:
                res |= free_vars(val)
    return res

def instantiate(env_type, env):
    t = env_type[1]
    free_t = free_vars(t)
    free_env = free_vars_env(env)
    to_inst = free_t - free_env
    s = {}
    for v in to_inst:
        s[v] = fresh()
    return apply(t, s)

def validate(term):
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    tag = term[0]
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int): raise ValueError("Malformed term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
    elif tag == "lam":
        if len(term) != 3: raise ValueError("Malformed term")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
        validate(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2]); validate(term[3])
    elif tag == "pair":
        if len(term) != 3: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2])
    elif tag in ("fst", "snd"):
        if len(term) != 2: raise ValueError("Malformed term")
        validate(term[1])
    elif tag in ("let", "letrec"):
        if len(term) != 4: raise ValueError("Malformed term")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
        validate(term[2]); validate(term[3])
    else:
        raise ValueError("Malformed term")

def _print_type(t):
    if isinstance(t, Int): return "Int"
    if isinstance(t, Bool): return "Bool"
    if isinstance(t, Var): return t.name
    if isinstance(t, Fun):
        a = _print_type(t.a)
        b = _print_type(t.b)
        if isinstance(t.a, Fun): a = f"({a})"
        return f"{a} -> {b}"
    if isinstance(t, Pair):
        return f"({_print_type(t.a)}, {_print_type(t.b)})"
    return "?"

def infer(term, env=None, s=None):
    global _fresh_counter
    _fresh_counter = 0
    if env is None:
        v = fresh()
        v.name = "a"
        init_env = [{"add": Fun(Int, Fun(Int, Int)),
                     "eq": Fun(v, Fun(v, Bool)),
                     "not": Fun(Bool, Bool)}]
        init_env[0] = {k: ("poly", v) for k, v in init_env[0].items()}
        env = init_env
    if s is None: s = {}

    validate(term)
    tag = term[0]

    if tag == "int":
        return Int(), s
    elif tag == "bool":
        return Bool(), s
    elif tag == "var":
        name = term[1]
        for scope in reversed(env):
            if name in scope:
                val = scope[name]
                if isinstance(val, tuple) and val[0] == "poly":
                    return instantiate(val, env), s
                return val, s
        raise ValueError("Unbound variable")
    elif tag == "lam":
        name, body = term[1], term[2]
        t = fresh()
        new_env = env + [{name: t}]
        body_t, s = infer(body, new_env, s)
        return Fun(t, body_t), s
    elif tag == "app":
        f, arg = term[1], term[2]
        f_t, s = infer(f, env, s)
        arg_t, s = infer(arg, env, s)
        res = fresh()
        s = unify(f_t, Fun(arg_t, res), s)
        return apply(res, s), s
    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        c_t, s = infer(c, env, s)
        s = unify(c_t, Bool(), s)
        t_t, s = infer(t, env, s)
        e_t, s = infer(e, env, s)
        s = unify(t_t, e_t, s)
        return apply(t_t, s), s
    elif tag == "pair":
        a, b = term[1], term[2]
        a_t, s = infer(a, env, s)
        b_t, s = infer(b, env, s)
        return Pair(a_t, b_t), s
    elif tag == "fst":
        e = term[1]
        e_t, s = infer(e, env, s)
        a = fresh(); b = fresh()
        s = unify(e_t, Pair(a, b), s)
        return apply(a, s), s
    elif tag == "snd":
        e = term[1]
        e_t, s = infer(e, env, s)
        a = fresh(); b = fresh()
        s = unify(e_t, Pair(a, b), s)
        return apply(b, s), s
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_t, s = infer(e1, env, s)
        new_env = env + [{name: ("poly", e1_t)}]
        return infer(e2, new_env, s)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        v = fresh()
        new_env1 = env + [{name: v}]
        e1_t, s = infer(e1, new_env1, s)
        s = unify(v, e1_t, s)
        e1_t = apply(e1_t, s)
        new_env2 = env + [{name: ("poly", e1_t)}]
        return infer(e2, new_env2, s)
    raise ValueError("Malformed term")

def _collect_vars(t):
    if isinstance(t, Var): return [t]
    if isinstance(t, Fun): return _collect_vars(t.a) + _collect_vars(t.b)
    if isinstance(t, Pair): return _collect_vars(t.a) + _collect_vars(t.b)
    return []

def _rename_vars(t, mapping):
    if isinstance(t, Var): return mapping[t]
    if isinstance(t, Fun): return Fun(_rename_vars(t.a, mapping), _rename_vars(t.b, mapping))
    if isinstance(t, Pair): return Pair(_rename_vars(t.a, mapping), _rename_vars(t.b, mapping))
    return t

def infer(term):
    t, _ = infer(term)
    raw_vars = _collect_vars(t)
    seen = set()
    unique_vars = []
    for v in raw_vars:
        if v not in seen:
            seen.add(v)
            unique_vars.append(v)
    names = []
    idx = 0
    for _ in unique_vars:
        if idx < 26:
            names.append(chr(ord('a') + idx))
        else:
            base = idx // 26 - 1
            offset = idx % 26
            names.append(f"{chr(ord('a') + offset)}{base + 1}")
        idx += 1
    mapping = {v: Var(i) for i, v in enumerate(unique_vars)}
    for v in mapping.values():
        v.name = names[unique_vars.index(v)]
    t = _rename_vars(t, mapping)
    return _print_type(t)

import sys

# Type representation
class Type:
    pass

class Int(Type):
    def __repr__(self): return "Int"

class Bool(Type):
    def __repr__(self): return "Bool"

class Var(Type):
    def __init__(self, i):
        self.i = i
    def __hash__(self): return self.i
    def __eq__(self, other):
        return isinstance(other, Var) and self.i == other.i
    def __repr__(self): return f"Var({self.i})"

class Fun(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def __repr__(self): return f"Fun({self.a}, {self.b})"

class Pair(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def __repr__(self): return f"Pair({self.a}, {self.b})"

# Fresh variable counter
_fresh_counter = 0

def fresh():
    global _fresh_counter
    v = Var(_fresh_counter)
    _fresh_counter += 1
    return v

# Substitution application
def apply_subst(t, s):
    if isinstance(t, Var):
        return s.get(t, t)
    if isinstance(t, Fun):
        return Fun(apply_subst(t.a, s), apply_subst(t.b, s))
    if isinstance(t, Pair):
        return Pair(apply_subst(t.a, s), apply_subst(t.b, s))
    return t

# Occurs check
def occurs(v, t):
    if t == v: return True
    if isinstance(t, Fun): return occurs(v, t.a) or occurs(v, t.b)
    if isinstance(t, Pair): return occurs(v, t.a) or occurs(v, t.b)
    return False

# Unification
def unify(t1, t2, s):
    t1 = apply_subst(t1, s)
    t2 = apply_subst(t2, s)
    if t1 == t2: return s
    if isinstance(t1, Var):
        if occurs(t1, t2): raise ValueError("Occurs check")
        return {t1: t2} | s
    if isinstance(t2, Var):
        if occurs(t2, t1): raise ValueError("Occurs check")
        return {t2: t1} | s
    if isinstance(t1, Fun) and isinstance(t2, Fun):
        s = unify(t1.a, t2.a, s)
        return unify(t1.b, t2.b, s)
    if isinstance(t1, Pair) and isinstance(t2, Pair):
        s = unify(t1.a, t2.a, s)
        return unify(t1.b, t2.b, s)
    raise ValueError("Type mismatch")

# Free type variables
def free_vars(t):
    if isinstance(t, Var): return {t}
    if isinstance(t, Fun): return free_vars(t.a) | free_vars(t.b)
    if isinstance(t, Pair): return free_vars(t.a) | free_vars(t.b)
    return set()

# Free vars in environment
def free_vars_env(env):
    res = set()
    for scope in env:
        for _, val in scope.items():
            if isinstance(val, tuple) and val[0] == "poly":
                res |= free_vars(val[1])
            else:
                res |= free_vars(val)
    return res

# Generalization
def generalize(t, env):
    free_t = free_vars(t)
    free_env = free_vars_env(env)
    to_gen = free_t - free_env
    s_gen = {}
    for v in to_gen:
        s_gen[v] = fresh()
    t_gen = apply_subst(t, s_gen)
    return t_gen, s_gen

# Validation
def validate(term):
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    tag = term[0]
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int): raise ValueError("Malformed term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
    elif tag == "lam":
        if len(term) != 3: raise ValueError("Malformed term")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
        validate(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2]); validate(term[3])
    elif tag == "pair":
        if len(term) != 3: raise ValueError("Malformed term")
        validate(term[1]); validate(term[2])
    elif tag in ("fst", "snd"):
        if len(term) != 2: raise ValueError("Malformed term")
        validate(term[1])
    elif tag in ("let", "letrec"):
        if len(term) != 4: raise ValueError("Malformed term")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed term")
        validate(term[2]); validate(term[3])
    else:
        raise ValueError("Malformed term")

# Printing
def print_type(t):
    if isinstance(t, Int): return "Int"
    if isinstance(t, Bool): return "Bool"
    if isinstance(t, Var): return t.name
    if isinstance(t, Fun):
        a = print_type(t.a)
        b = print_type(t.b)
        if isinstance(t.a, Fun): a = f"({a})"
        return f"{a} -> {b}"
    if isinstance(t, Pair):
        return f"({print_type(t.a)}, {print_type(t.b)})"
    return "?"

def collect_vars(t):
    if isinstance(t, Var): return [t]
    if isinstance(t, Fun): return collect_vars(t.a) + collect_vars(t.b)
    if isinstance(t, Pair): return collect_vars(t.a) + collect_vars(t.b)
    return []

def rename_vars(t, mapping):
    if isinstance(t, Var): return mapping[t]
    if isinstance(t, Fun): return Fun(rename_vars(t.a, mapping), rename_vars(t.b, mapping))
    if isinstance(t, Pair): return Pair(rename_vars(t.a, mapping), rename_vars(t.b, mapping))
    return t

# Inference
def infer(term, env=None, s=None):
    global _fresh_counter
    _fresh_counter = 0
    if env is None:
        v = fresh()
        v.name = "a"
        init_env = [{"add": Fun(Int, Fun(Int, Int)),
                     "eq": Fun(v, Fun(v, Bool)),
                     "not": Fun(Bool, Bool)}]
        init_env[0] = {k: ("poly", v) for k, v in init_env[0].items()}
        env = init_env
    if s is None: s = {}

    validate(term)
    tag = term[0]

    if tag == "int":
        return Int(), s
    elif tag == "bool":
        return Bool(), s
    elif tag == "var":
        name = term[1]
        for scope in reversed(env):
            if name in scope:
                val = scope[name]
                if isinstance(val, tuple) and val[0] == "poly":
                    t_scheme = val[1]
                    # Instantiate: replace free vars in scheme with fresh vars not free in env
                    free_t = free_vars(t_scheme)
                    free_env = free_vars_env(env)
                    to_inst = free_t - free_env
                    s_inst = {}
                    for v in to_inst:
                        s_inst[v] = fresh()
                    return apply_subst(t_scheme, s_inst), s
                return val, s
        raise ValueError("Unbound variable")
    elif tag == "lam":
        name, body = term[1], term[2]
        t = fresh()
        new_env = env + [{name: t}]
        body_t, s = infer(body, new_env, s)
        return Fun(t, body_t), s
    elif tag == "app":
        f, arg = term[1], term[2]
        f_t, s = infer(f, env, s)
        arg_t, s = infer(arg, env, s)
        res = fresh()
        s = unify(f_t, Fun(arg_t, res), s)
        return apply_subst(res, s), s
    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        c_t, s = infer(c, env, s)
        s = unify(c_t, Bool(), s)
        t_t, s = infer(t, env, s)
        e_t, s = infer(e, env, s)
        s = unify(t_t, e_t, s)
        return apply_subst(t_t, s), s
    elif tag == "pair":
        a, b = term[1], term[2]
        a_t, s = infer(a, env, s)
        b_t, s = infer(b, env, s)
        return Pair(a_t, b_t), s
    elif tag == "fst":
        e = term[1]
        e_t, s = infer(e, env, s)
        a = fresh(); b = fresh()
        s = unify(e_t, Pair(a, b), s)
        return apply_subst(a, s), s
    elif tag == "snd":
        e = term[1]
        e_t, s = infer(e, env, s)
        a = fresh(); b = fresh()
        s = unify(e_t, Pair(a, b), s)
        return apply_subst(b, s), s
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_t, s = infer(e1, env, s)
        e1_t = apply_subst(e1_t, s)
        e1_t_gen, s_gen = generalize(e1_t, env)
        # Update s with s_gen to keep consistency, though not strictly necessary for e2
        # But s_gen maps old vars to fresh vars.
        # We should apply s_gen to s? No, s maps vars to types.
        # If s has mappings for vars in e1_t, they are already applied.
        # s_gen introduces new vars.
        # It's safer to just proceed.
        new_env = env + [{name: ("poly", e1_t_gen)}]
        return infer(e2, new_env, s)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        v = fresh()
        new_env1 = env + [{name: v}]
        e1_t, s = infer(e1, new_env1, s)
        e1_t = apply_subst(e1_t, s)
        v = apply_subst(v, s)
        s = unify(v, e1_t, s)
        e1_t = apply_subst(e1_t, s)
        e1_t_gen, s_gen = generalize(e1_t, env)
        new_env2 = env + [{name: ("poly", e1_t_gen)}]
        return infer(e2, new_env2, s)
    raise ValueError("Malformed term")

def infer(term):
    t, _ = infer(term)
    raw_vars = collect_vars(t)
    seen = set()
    unique_vars = []
    for v in raw_vars:
        if v not in seen:
            seen.add(v)
            unique_vars.append(v)
    names = []
    idx = 0
    for _ in unique_vars:
        if idx < 26:
            names.append(chr(ord('a') + idx))
        else:
            base = idx // 26 - 1
            offset = idx % 26
            names.append(f"{chr(ord('a') + offset)}{base + 1}")
        idx += 1
    mapping = {v: Var(i) for i, v in enumerate(unique_vars)}
    for v in mapping.values():
        v.name = names[unique_vars.index(v)]
    t = rename_vars(t, mapping)
    return print_type(t)

class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.kind == other.kind and self.args == other.args
    def __hash__(self):
        return hash((self.kind, self.args))

def apply_subs(t, subs):
    if t.kind == 'Var':
        return subs.get(t.args[0], t)
    return Type(t.kind, *[apply_subs(a, subs) for a in t.args])

def var_in(id, t, subs):
    t = apply_subs(t, subs)
    def check(tt):
        if tt.kind == 'Var':
            return tt.args[0] == id
        return any(check(a) for a in tt.args)
    return check(t)

def unify(t1, t2, subs):
    t1 = apply_subs(t1, subs)
    t2 = apply_subs(t2, subs)
    if t1 == t2:
        return subs
    if t1.kind == 'Var':
        if var_in(t1.args[0], t2, subs):
            raise ValueError("Occurs check")
        subs[t1.args[0]] = t2
        return subs
    if t2.kind == 'Var':
        if var_in(t2.args[0], t1, subs):
            raise ValueError("Occurs check")
        subs[t2.args[0]] = t1
        return subs
    if t1.kind != t2.kind:
        raise ValueError("Type mismatch")
    if t1.kind in ('Fun', 'Pair'):
        subs = unify(t1.args[0], t2.args[0], subs)
        subs = unify(t1.args[1], t2.args[1], subs)
        return subs
    raise ValueError("Type mismatch")

def get_free_vars(t, env):
    def collect(tt, res):
        if tt.kind == 'Var':
            res.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a, res)
    res = set()
    collect(t, res)
    for scope in env:
        for _, (ty, _) in scope.items():
            collect(ty, res)
    return res

class State:
    def __init__(self):
        self.subs = {}
        self.fresh_id = 0
        self.env = [{}]
        v1, v2 = self.fresh(), self.fresh()
        self.env[0]['add'] = (Type('Fun', Type('Fun', Type('Int'), Type('Int')), Type('Int')), set())
        self.env[0]['eq'] = (Type('Fun', Type('Fun', Type('Var', v1), Type('Var', v1)), Type('Bool')), set())
        self.env[0]['not'] = (Type('Fun', Type('Bool'), Type('Bool')), set())

    def fresh(self):
        v = self.fresh_id
        self.fresh_id += 1
        return v

def gen(t, env):
    free = get_free_vars(t, env)
    return (t, free)

def inst(poly, state):
    t, quantified = poly
    new_subs = {}
    for v in quantified:
        new_subs[v] = Type('Var', state.fresh())
    return apply_subs(t, new_subs)

def infer_term(term, state):
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Malformed term")
        return Type('Int')
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed term")
        return Type('Bool')
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name = term[1]
        for scope in reversed(state.env):
            if name in scope:
                return inst(scope[name], state)
        raise ValueError("Unbound variable")
    elif tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name, body = term[1], term[2]
        v = state.fresh()
        arg_type = Type('Var', v)
        state.env.append({name: (arg_type, set())})
        body_type = infer_term(body, state)
        state.env.pop()
        return Type('Fun', arg_type, body_type)
    elif tag == 'app':
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, arg = term[1], term[2]
        f_type = infer_term(f, state)
        arg_type = infer_term(arg, state)
        ret_type = Type('Var', state.fresh())
        state.subs = unify(f_type, Type('Fun', arg_type, ret_type), state.subs)
        return apply_subs(ret_type, state.subs)
    elif tag == 'if':
        if len(term) != 4:
            raise ValueError("Malformed term")
        c, t, e = term[1], term[2], term[3]
        c_type = infer_term(c, state)
        t_type = infer_term(t, state)
        e_type = infer_term(e, state)
        state.subs = unify(c_type, Type('Bool'), state.subs)
        state.subs = unify(t_type, e_type, state.subs)
        return apply_subs(t_type, state.subs)
    elif tag == 'pair':
        if len(term) != 3:
            raise ValueError("Malformed term")
        a, b = term[1], term[2]
        return Type('Pair', infer_term(a, state), infer_term(b, state))
    elif tag == 'fst':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        state.subs = unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t1, state.subs)
    elif tag == 'snd':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        state.subs = unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t2, state.subs)
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        e1_type = infer_term(e1, state)
        poly = gen(e1_type, state.env)
        state.env.append({name: poly})
        e2_type = infer_term(e2, state)
        state.env.pop()
        return e2_type
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        v = state.fresh()
        rec_type = Type('Var', v)
        state.env.append({name: (rec_type, set())})
        e1_type = infer_term(e1, state)
        state.subs = unify(rec_type, e1_type, state.subs)
        e1_type = apply_subs(e1_type, state.subs)
        poly = gen(e1_type, state.env)
        state.env[-1][name] = poly
        e2_type = infer_term(e2, state)
        state.env.pop()
        return e2_type
    else:
        raise ValueError("Malformed term")

def type_to_str(t, subs):
    t = apply_subs(t, subs)
    seen = []
    seen_set = set()
    def collect(tt):
        if tt.kind == 'Var':
            if tt.args[0] not in seen_set:
                seen.append(tt.args[0])
                seen_set.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)
    collect(t)

    names = []
    for i in range(len(seen)):
        if i < 26:
            names.append(chr(ord('a') + i))
        else:
            q, r = divmod(i - 26, 26)
            names.append(chr(ord('a') + r) + str(q + 1))
    var_map = {v: names[i] for i, v in enumerate(seen)}

    def print_tt(tt):
        if tt.kind == 'Var':
            return var_map[tt.args[0]]
        elif tt.kind == 'Int':
            return 'Int'
        elif tt.kind == 'Bool':
            return 'Bool'
        elif tt.kind == 'Fun':
            left = print_tt(tt.args[0])
            right = print_tt(tt.args[1])
            if tt.args[0].kind == 'Fun':
                left = f"({left})"
            return f"{left} -> {right}"
        elif tt.kind == 'Pair':
            return f"({print_tt(tt.args[0])}, {print_tt(tt.args[1])})"
        return ''
    return print_tt(t)

def infer(term):
    state = State()
    res_type = infer_term(term, state)
    return type_to_str(res_type, state.subs)

class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
