def phi_blocks(n, edges, entry, defs):
    # Input validation
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if isinstance(entry, bool) or not isinstance(entry, int) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs")
        if isinstance(e[0], bool) or not isinstance(e[0], int) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if isinstance(e[1], bool) or not isinstance(e[1], int) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")
    for k, v in defs.items():
        try:
            it = iter(v)
        except TypeError:
            raise ValueError("defs values must be iterables")
        for node in it:
            if isinstance(node, bool) or not isinstance(node, int) or not (0 <= node < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")
            break  # Just check first element type, rest will be checked by iterator if needed, but spec says iterable of ints. We'll check all to be safe.
        for node in v:
            if isinstance(node, bool) or not isinstance(node, int) or not (0 <= node < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")

    # Build adjacency lists
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Reachability from entry
    reachable = [False] * n
    q = deque([entry])
    reachable[entry] = True
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    R = order
    nR = len(R)
    pos = {v: i for i, v in enumerate(R)}

    # Dominator tree construction (CHK algorithm)
    idom = [None] * n
    idom[entry] = entry
    parent_dom = [None] * n
    parent_dom[entry] = entry
    depth = [0] * n

    uf = list(range(n))
    def find(i):
        root = i
        while uf[root] != root:
            root = uf[root]
        curr = i
        while curr != root:
            nxt = uf[curr]
            uf[curr] = root
            curr = nxt
        return root

    def intersect(u, v):
        u = find(u)
        v = find(v)
        while u != v:
            if depth[u] > depth[v]:
                u = parent_dom[u]
            elif depth[v] > depth[u]:
                v = parent_dom[v]
            else:
                u = parent_dom[u]
                v = parent_dom[v]
            u = find(u)
            v = find(v)
        return u

    # DFS post-order for CHK
    post_order = []
    visited = set()
    stack = [entry]
    while stack:
        u = stack[-1]
        if u not in visited:
            visited.add(u)
            for v in adj[u]:
                if reachable[v] and v not in visited:
                    stack.append(v)
        else:
            post_order.append(stack.pop())

    # First pass
    for v in reversed(post_order):
        if v == entry: continue
        w = v
        for u in rev_adj[v]:
            if reachable[u]:
                w = intersect(w, u)
        idom[v] = w
        parent_dom[v] = w
        depth[v] = depth[w] + 1

    # Second pass
    for v in post_order:
        if v == entry: continue
        idom[v] = idom[idom[v]]

    # Binary lifting for LCA in dominator tree
    LOG = nR.bit_length()
    up = [[-1] * n for _ in range(LOG)]
    up[0] = list(idom)
    for i in range(1, LOG):
        for v in R:
            p = up[i-1][v]
            up[i][v] = up[i-1][p] if p != -1 else -1

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for i in range(LOG-1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                u = up[i][u]
        if u == v: return u
        for i in range(LOG-1, -1, -1):
            if up[i][u] != up[i][v]:
                u = up[i][u]
                v = up[i][v]
        return up[0][u]

    # Compute Dominance Frontiers
    DF = [set() for _ in range(n)]
    for p in R:
        for y in adj[p]:
            if not reachable[y]: continue
            l = lca(p, y)
            curr = p
            while curr != l:
                DF[curr].add(y)
                curr = idom[curr]
            if curr == l:
                # l dominates p. l strictly dominates y iff l != y.
                # We only add y to DF[l] if l does not strictly dominate y.
                if l == y:
                    DF[l].add(y)

    # Compute P for each variable
    result = {}
    for var, def_nodes in defs.items():
        S = set(d for d in def_nodes if reachable[d])
        if not S:
            result[var] = []
            continue

        P = set(S)
        queue = deque(S)
        added = set(S)

        while queue:
            x = queue.popleft()
            for y in DF[x]:
                if y not in added:
                    added.add(y)
                    P.add(y)
                    queue.append(y)

        result[var] = sorted(P)

    return result

