    S = set(S)

    if not isinstance(piles, list):
        raise ValueError("piles must be a list")
    for p in piles:
        if type(p) is not int or isinstance(p, bool):
            raise ValueError("piles items must be ints")
        if p < 0 or p > 10**18:
            raise ValueError("piles items must be in 0..10**18")

    if not piles:
        return {"grundy": [], "winner": "second", "moves": []}

    k = max(S)
    G = [0]
    seen = {}

    n = 1
    while True:
        # Compute G(n)
        reachable = set()
        for s in S:
            if n - s >= 0:
                reachable.add(G[n - s])
        g_n = 0
        while g_n in reachable:
            g_n += 1
        G.append(g_n)

        # Check for cycle once we have a full window of size k
        if n >= k - 1:
            state = tuple(G[n - k + 1 : n + 1])
            if state in seen:
                pre_period_start = seen[state]
                period = n - pre_period_start
                break
            else:
                seen[state] = n
        n += 1

    def get_grundy(N):
        if N < len(G):
            return G[N]
        offset = N - pre_period_start
        return G[pre_period_start + (offset % period)]

    grundy_vals = [get_grundy(p) for p in piles]
    xor_sum = 0
    for g in grundy_vals:
        xor_sum ^= g

    winner = "first" if xor_sum != 0 else "second"

    moves = []
    if winner == "first":
        for i, p in enumerate(piles):
            g_p = grundy_vals[i]
            target = xor_sum ^ g_p
            for s in sorted(S):
                if s > p:
                    break
                if get_grundy(p - s) == target:
                    moves.append((i, s))

    moves.sort()
    return {"grundy": grundy_vals, "winner": winner, "moves": moves}

def sub_game(S, piles):
    # Input validation
    if not isinstance(S, (list, tuple, set, frozenset)):
        raise ValueError("S must be a list, tuple, set or frozenset")
    if not isinstance(piles, list):
        raise ValueError("piles must be a list")
    if len(S) == 0:
        raise ValueError("S must not be empty")
    if len(piles) > 50:
        raise ValueError("piles must have at most 50 elements")

    for item in S:
        if isinstance(item, bool) or not isinstance(item, int) or item < 1 or item > 40:
            raise ValueError("Items in S must be integers in 1..40")

    if isinstance(S, (list, tuple)):
        if len(S) != len(set(S)):
            raise ValueError("S must not contain repeated items")

    for item in piles:
        if isinstance(item, bool) or not isinstance(item, int) or item < 0 or item > 10**18:
            raise ValueError("Items in piles must be integers in 0..10**18")

    S_list = sorted(list(S))
    M = max(S_list)

    # Compute Grundy values and detect period
    history = [0]
    seen_windows = {}
    period_start = -1
    period_length = -1

    idx = 0
    while True:
        idx += 1
        # Compute g(idx)
        reachable = set()
        for s in S_list:
            if s > idx:
                break
            reachable.add(history[idx - s])

        g_val = 0
        while g_val in reachable:
            g_val += 1
        history.append(g_val)

        if idx >= M - 1:
            window = tuple(history[idx - M + 1 : idx + 1])
            if window in seen_windows:
                first_occ = seen_windows[window]
                period_start = first_occ - M + 1
                period_length = idx - first_occ
                break
            else:
                seen_windows[window] = idx

        # Safety break (should not be reached for valid inputs within time limits)
        if idx > 100000:
            break

    # Compute Grundy values for all piles
    grundy_values = []
    for n in piles:
        if n < len(history):
            g = history[n]
        else:
            if period_start == -1:
                g = 0
            else:
                offset = n - period_start
                index_in_period = offset % period_length
                g = history[period_start + index_in_period]
        grundy_values.append(g)

    # Compute Nim-sum
    nim_sum = 0
    for g in grundy_values:
        nim_sum ^= g

    winner = "first" if nim_sum != 0 else "second"

    # Find all winning moves
    winning_moves = []
    if winner == "first":
        for i, n in enumerate(piles):
            g_i = grundy_values[i]
            target_g = nim_sum ^ g_i
            for s in S_list:
                if s > n:
                    break
                rem = n - s
                if rem < len(history):
                    g_rem = history[rem]
                else:
                    if period_start == -1:
                        g_rem = 0
                    else:
                        offset = rem - period_start
                        index_in_period = offset % period_length
                        g_rem = history[period_start + index_in_period]

                if g_rem == target_g:
                    winning_moves.append((i, s))

    winning_moves.sort()

    return {
        "grundy": grundy_values,
        "winner": winner,
        "moves": winning_moves
    }

import math

def lattice_count(poly):
    if not isinstance(poly, (list, tuple)):
        raise ValueError("poly must be a list or tuple")
    n = len(poly)
    if not (3 <= n <= 2000):
        raise ValueError("poly must have 3..2000 vertices")

    verts = []
    for v in poly:
        if not isinstance(v, (list, tuple)) or len(v) != 2:
            raise ValueError("Each vertex must be a list/tuple of two ints")
        x, y = v
        if type(x) is not int or type(y) is not int:
            raise ValueError("Coordinates must be ints")
        if abs(x) > 10**9 or abs(y) > 10**9:
            raise ValueError("Coordinates must be <= 10^9")
        verts.append((x, y))

    merged = []
    if not verts:
        raise ValueError("Empty")
    merged.append(verts[0])
    for i in range(1, len(verts)):
        if verts[i] != verts[i-1]:
            merged.append(verts[i])

    if len(merged) > 1 and merged[-1] == merged[0]:
        merged.pop()

    if len(merged) < 3:
        raise ValueError("Fewer than 3 vertices after merging")

    v = merged
    m = len(v)

    # Check spikes (0-degree turns)
    for i in range(m):
        p_prev = v[(i-1) % m]
        p_curr = v[i]
        p_next = v[(i+1) % m]
        ux = p_curr[0] - p_prev[0]
        uy = p_curr[1] - p_prev[1]
        wx = p_next[0] - p_curr[0]
        wy = p_next[1] - p_curr[1]
        cp = ux * wy - uy * wx
        dot = ux * wx + uy * wy
        if cp == 0 and dot < 0:
            raise ValueError("Spike detected")

    # Check non-neighbouring edge intersections
    for i in range(m):
        x1, y1 = v[i]
        x2, y2 = v[(i+1) % m]
        for j in range(i+2, m):
            if i == 0 and j == m-1:
                continue
            x3, y3 = v[j]
            x4, y4 = v[(j+1) % m]

            d1 = (x4-x3)*(y1-y3) - (y4-y3)*(x1-x3)
            d2 = (x4-x3)*(y2-y3) - (y4-y3)*(x2-x3)
            d3 = (x2-x1)*(y3-y1) - (y2-y1)*(x3-x1)
            d4 = (x2-x1)*(y4-y1) - (y2-y1)*(x4-x1)

            if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
               ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
                raise ValueError("Non-neighbouring edges intersect")

            if d1 == 0:
                if min(x3, x4) <= x1 <= max(x3, x4) and min(y3, y4) <= y1 <= max(y3, y4):
                    raise ValueError("Non-neighbouring edges intersect")
            if d2 == 0:
                if min(x3, x4) <= x2 <= max(x3, x4) and min(y3, y4) <= y2 <= max(y3, y4):
                    raise ValueError("Non-neighbouring edges intersect")
            if d3 == 0:
                if min(x1, x2) <= x3 <= max(x1, x2) and min(y1, y2) <= y3 <= max(y1, y2):
                    raise ValueError("Non-neighbouring edges intersect")
            if d4 == 0:
                if min(x1, x2) <= x4 <= max(x1, x2) and min(y1, y2) <= y4 <= max(y1, y2):
                    raise ValueError("Non-neighbouring edges intersect")

    # Compute twice_area using shoelace formula
    twice_area = 0
    for i in range(m):
        x1, y1 = v[i]
        x2, y2 = v[(i+1) % m]
        twice_area += x1 * y2 - x2 * y1
    twice_area = abs(twice_area)
    if twice_area == 0:
        raise ValueError("Zero area")

    # Compute boundary points using gcd of edge deltas
    boundary = 0
    for i in range(m):
        x1, y1 = v[i]
        x2, y2 = v[(i+1) % m]
        boundary += math.gcd(abs(x1 - x2), abs(y1 - y2))

    # Pick's theorem: Area = I + B/2 - 1  =>  2*Area = 2*I + B - 2
    interior = (twice_area - boundary + 2) // 2

    return (interior, boundary, twice_area)

def round_dec(s, places, mode):
    # Validate inputs
    if not isinstance(s, str) or not isinstance(places, int) or isinstance(places, bool):
        raise ValueError("Invalid input types")
    if not isinstance(mode, str):
        raise ValueError("Invalid mode type")
    if mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("Invalid mode")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")

    # Parse s
    if not s:
        raise ValueError("s is empty")

    sign = 1
    if s[0] in '+-':
        sign = -1 if s[0] == '-' else 1
        s = s[1:]
    if not s:
        raise ValueError("s has only a sign")

    exp = 0
    e_idx = -1
    for i, c in enumerate(s):
        if c in 'eE':
            e_idx = i
            break

    if e_idx != -1:
        exp_str = s[e_idx+1:]
        if not exp_str:
            raise ValueError("Invalid exponent")
        try:
            exp = int(exp_str)
        except ValueError:
            raise ValueError("Invalid exponent")
        s = s[:e_idx]

    if '.' in s:
        dot_idx = s.index('.')
        int_part = s[:dot_idx]
        frac_part = s[dot_idx+1:]
    else:
        int_part = s
        frac_part = ""

    if not int_part and not frac_part:
        raise ValueError("No digits in s")

    digits = int_part + frac_part
    digits = digits.lstrip('0')
    if not digits:
        mantissa = 0
        total_exp = 0
    else:
        mantissa = int(digits)
        total_exp = exp - len(frac_part)

    # Rounding logic
    shift = places
    K = total_exp + shift

    if K >= 0:
        # Already a multiple of 10**(-places), or exactly represents it
        final_mantissa = mantissa * (10 ** K)
    else:
        d = -K
        divisor = 10 ** d
        abs_m = abs(mantissa)
        quotient = abs_m // divisor
        remainder = abs_m % divisor
        half = divisor // 2

        add = 0
        if remainder < half:
            add = 0
        elif remainder > half:
            add = divisor
        else: # tie
            if mode == "half_even":
                add = divisor if (quotient & 1) else 0
            elif mode == "half_up":
                add = divisor
            elif mode == "half_down":
                add = 0
            elif mode == "floor":
                add = divisor if sign < 0 else 0
            elif mode == "ceil":
                add = divisor if sign > 0 else 0
            elif mode == "up":
                add = divisor
            elif mode == "down":
                add = 0

        new_abs_m = (quotient + (1 if add else 0)) * divisor
        final_mantissa = sign * new_abs_m

    # Size limit check
    if final_mantissa == 0:
        total_digits = 1
    elif places > 0:
        s_m = str(abs(final_mantissa))
        total_digits = len(s_m) if len(s_m) > places else places + 1
    else:
        if -places > 4000:
            raise ValueError("Output exceeds 4000 digits")
        total_digits = len(str(abs(final_mantissa))) + (-places)

    if total_digits > 4000:
        raise ValueError("Output exceeds 4000 digits")

    # Format output
    if places > 0:
        s_m = str(abs(final_mantissa))
        if len(s_m) <= places:
            int_part = "0"
            frac_part = s_m.zfill(places)
        else:
            int_part = s_m[:-places]
            frac_part = s_m[-places:]
        res = f"{int_part}.{frac_part}"
        if final_mantissa < 0:
            res = "-" + res
        return res
    else:
        if final_mantissa == 0:
            return "0"
        abs_m = abs(final_mantissa)
        res = f"{abs_m}{'0' * (-places)}"
        if final_mantissa < 0:
            res = "-" + res
        return res

def round_dec(s, places, mode):
    if not isinstance(places, int) or isinstance(places, bool):
        raise ValueError("places must be an int")
    if not isinstance(s, str):
        raise ValueError("s must be a str")
    if mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("Invalid mode")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")

    # Parse s
    if not s:
        raise ValueError("Empty string")

    sign = 1
    if s[0] == '-':
        sign = -1
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    # Split exponent
    if 'e' in s or 'E' in s:
        mantissa, exp_str = s.split('e' if 'e' in s else 'E')
        exp_val = int(exp_str)
    else:
        mantissa = s
        exp_val = 0

    # Parse mantissa
    if '.' in mantissa:
        int_part, frac_part = mantissa.split('.', 1)
        n_frac = len(frac_part)
        D = int_part + frac_part
    else:
        D = mantissa
        n_frac = 0

    if not D:
        raise ValueError("No digits")

    # Adjust exponent
    exp_val -= n_frac

    # Determine shift
    shift = exp_val + places

    # Handle shift >= 0 (integer result or appending zeros)
    if shift >= 0:
        # D might have leading zeros
        D_clean = D.lstrip('0') or '0'
        Q_str = D_clean + '0' * shift
        Q = int(Q_str) * sign
    else:
        # shift < 0, need to round
        d = -shift
        len_D = len(D)

        if d >= len_D:
            q_str = ''
            r_str = D
        else:
            q_str = D[:-d]
            r_str = D[-d:]

        # Check r properties without big ints
        r_is_zero = all(c == '0' for c in r_str)
        if d > 0:
            r_tie = (r_str[0] == '1' and all(c == '0' for c in r_str[1:]))
            r_gt_half = (r_str[0] > '1') or (r_str[0] == '1' and not all(c == '0' for c in r_str[1:]))
        else:
            r_tie = False
            r_gt_half = False

        # q parity
        if q_str:
            q_even = (int(q_str[-1]) % 2 == 0)
        else:
            q_even = True  # 0 is even

        # Determine if we round up
        round_up = False
        if r_is_zero:
            round_up = False
        elif mode == 'half_even':
            round_up = not q_even
        elif mode == 'half_up':
            round_up = True
        elif mode == 'half_down':
            round_up = r_gt_half
        elif mode == 'floor':
            round_up = False
        elif mode == 'ceil':
            round_up = True
        elif mode == 'up':
            round_up = True
        elif mode == 'down':
            round_up = False

        if round_up:
            q_val = int(q_str) + 1 if q_str else 1
        else:
            q_val = int(q_str) if q_str else 0

        Q = sign * q_val

    # Format output
    abs_Q = abs(Q)
    sign_str = '-' if Q < 0 else ''

    if places == 0:
        res = str(abs_Q)
    elif places > 0:
        Q_str = str(abs_Q)
        if len(Q_str) < places:
            Q_str = '0' * (places - len(Q_str)) + Q_str
        int_part = Q_str[:-places] or '0'
        frac_part = Q_str[-places:]
        res = sign_str + int_part + '.' + frac_part
    else: # places < 0
        Q_str = str(abs_Q)
        Q_str += '0' * (-places)
        res = sign_str + Q_str

    # Size limit check
    # Count digits: integer part digits + fractional digits
    if '.' in res:
        int_d, frac_d = res.split('.')
        # int_d might have sign, remove it
        int_d = int_d.lstrip('-')
        total_digits = len(int_d) + len(frac_d)
    else:
        total_digits = len(res.lstrip('-'))

    if total_digits > 4000:
        raise ValueError("Output exceeds 4000 digits")

    return res

def round_dec(s, places, mode):
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if not isinstance(places, int) or isinstance(places, bool):
        raise ValueError("places must be an int")
    if places < -10**6 or places > 10**6:
        raise ValueError("places out of range")

    valid_modes = {"half_even", "half_up", "half_down", "floor", "ceil", "up", "down"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    # Parse s
    sign = '+'
    idx = 0
    if s[0] in '+-':
        sign = s[0]
        idx = 1

    # Find dot and exponent
    dot_pos = s.find('.', idx)
    exp_part = s.find('e', idx)
    if exp_part == -1:
        exp_part = s.find('E', idx)

    if exp_part == -1:
        exp = 0
        num_part = s[idx:]
    else:
        exp_str = s[exp_part+1:]
        if not exp_str:
            raise ValueError("Invalid exponent")
        exp = int(exp_str)
        num_part = s[idx:exp_part]

    if '.' in num_part:
        # num_part contains the dot
        dot_rel = num_part.index('.')
        digits = num_part.replace('.', '')
        # k is number of fractional digits
        k = len(num_part) - dot_rel - 1
    else:
        digits = num_part
        dot_rel = len(digits)
        k = 0

    if not digits or not any(c.isdigit() for c in digits):
        raise ValueError("Invalid digits")

    # Normalize digits: remove leading zeros, but keep at least one digit
    digits = digits.lstrip('0') or '0'
    L = len(digits)

    # Calculate shift
    # Value = sign * int(digits) * 10^(exp - k)
    # We want to round to places, so scale by 10^places
    # Scaled value = sign * int(digits) * 10^(exp - k + places)
    total_exp = exp - k + places

    if total_exp >= 0:
        # No rounding needed, just append zeros
        m_str = digits + '0' * total_exp
        m_str = m_str.lstrip('0') or '0'
    else:
        shift = -total_exp
        # Determine magnitude mode
        mag_mode_map = {
            'half_even': 'half_even',
            'half_up': 'half_up',
            'half_down': 'half_down',
            'floor': 'down',
            'ceil': 'up',
            'up': 'up',
            'down': 'down'
        }
        mag_mode = mag_mode_map[mode]
        m_str = _round_positive(digits, shift, mag_mode)

    # Apply sign
    if m_str == '0':
        result = '0'
    else:
        result = sign + m_str

    # Format result
    if places <= 0:
        # No decimal point
        if result == '0':
            return '0'
        # Append -places zeros
        zeros = '0' * (-places)
        return result + zeros
    else:
        # places > 0
        # result has no decimal point yet, it represents the value * 10^places
        # We need to insert decimal point
        # Pad with leading zeros if necessary
        if len(result) <= places:
            int_part = '0'
            frac_part = result.zfill(places)
        else:
            split = len(result) - places
            int_part = result[:split]
            frac_part = result[split:]

        # Remove leading zeros from int_part
        int_part = int_part.lstrip('0') or '0'

        # Check size limit
        if len(int_part) + len(frac_part) > 4000:
            raise ValueError("Output exceeds 4000 digits")

        return int_part + '.' + frac_part

def _round_positive(n_str, shift, mode):
    L = len(n_str)
    if shift == 0:
        return n_str

    if shift >= L:
        q_str = '0'
        r_str = n_str
    else:
        q_str = n_str[:L-shift]
        r_str = n_str[L-shift:]

    half_str = '5' + '0' * (shift - 1)

    # Compare r_str and half_str
    len_r = len(r_str)
    len_h = len(half_str)
    if len_r < len_h:
        cmp = -1
    elif len_r > len_h:
        cmp = 1
    else:
        if r_str < half_str:
            cmp = -1
        elif r_str > half_str:
            cmp = 1
        else:
            cmp = 0

    if cmp < 0:
        direction = 'down'
    elif cmp > 0:
        direction = 'up'
    else:
        direction = 'tie'

    if mode == 'half_even':
        if direction == 'tie':
            # Check if q_str is even
            last_digit = int(q_str[-1])
            direction = 'down' if last_digit % 2 == 0 else 'up'
    elif mode == 'half_up':
        if direction == 'tie':
            direction = 'up'
    elif mode == 'half_down':
        if direction == 'tie':
            direction = 'down'
    elif mode == 'up':
        direction = 'up'
    elif mode == 'down':
        direction = 'down'

    if direction == 'down':
        return q_str
    else:
        # direction == 'up'
        return _increment_string(q_str)

def _increment_string(s):
    # Increment a non-negative integer string by 1
    digits = list(s)
    i = len(digits) - 1
    while i >= 0:
        if digits[i] == '9':
            digits[i] = '0'
            i -= 1
        else:
            digits[i] = str(int(digits[i]) + 1)
            return ''.join(digits)
    return '1' + ''.join(digits)

def round_dec(s, places, mode):
    if not isinstance(s, str):
