    # Normalize digits
    digits_str = digits_str.lstrip('0') or '0'
    L = len(digits_str)

    # Value = sign * int(digits_str) * 10^(exp_val - frac_len)
    shift = exp_val - frac_len

    # Handle zero
    if digits_str == '0':
        if places <= 0:
            return '0'
        else:
            return '0.' + '0' * places

    # We want to round to places.
    # Value * 10^places = sign * int(digits_str) * 10^(shift + places)
    S = shift + places

    if S >= 0:
        # Exact integer magnitude
        Y_mag_str = digits_str + '0' * S
    else:
        k = -S
        if k >= L:
            if k > L:
                # Magnitude < 0.5, rounds to 0
                Y_mag_str = '0'
            else:
                # k == L, compare with 0.5
                T = "5" + "0" * (L - 1)
                if digits_str < T:
                    Y_mag_str = '0'
                elif digits_str > T:
                    Y_mag_str = '1'
                else:
                    # Tie
                    if mode == "half_even":
                        Y_mag_str = '0'
                    elif mode == "half_up":
                        Y_mag_str = '1'
                    elif mode == "half_down":
                        Y_mag_str = '0'
                    elif mode == "floor":
                        Y_mag_str = '1' if sign == -1 else '0'
                    elif mode == "ceil":
                        Y_mag_str = '1' if sign == 1 else '0'
                    elif mode == "up":
                        Y_mag_str = '1'
                    elif mode == "down":
                        Y_mag_str = '0'
        else:
            # k < L
            Q_str = digits_str[:L-k]
            R_str = digits_str[L-k:]
            T = "5" + "0" * (k - 1)

            if R_str < T:
                direction = 'down'
            elif R_str > T:
                direction = 'up'
            else:
                direction = 'tie'

            if direction == 'down':
                Y_mag_str = Q_str
            elif direction == 'up':
                Y_mag_str = _increment(Q_str)
            else:
                # Tie
                last_digit = int(Q_str[-1])
                is_even = (last_digit % 2 == 0)

                if mode == "half_even":
                    Y_mag_str = Q_str if is_even else _increment(Q_str)
                elif mode == "half_up":
                    Y_mag_str = _increment(Q_str)
                elif mode == "half_down":
                    Y_mag_str = Q_str
                elif mode == "floor":
                    Y_mag_str = Q_str if sign == 1 else _increment(Q_str)
                elif mode == "ceil":
                    Y_mag_str = _increment(Q_str) if sign == 1 else Q_str
                elif mode == "up":
                    Y_mag_str = _increment(Q_str)
                elif mode == "down":
                    Y_mag_str = Q_str

    # Format output
    if Y_mag_str == '0':
        if places <= 0:
            return '0'
        else:
            return '0.' + '0' * places

    if places <= 0:
        total_digits = len(Y_mag_str) + (-places)
        if total_digits > 4000:
            raise ValueError("Output exceeds 4000 digits")
        res = ('-' if sign == -1 else '') + Y_mag_str + '0' * (-places)
        return res
    else:
        len_Y = len(Y_mag_str)
        if len_Y <= places:
            total_digits = 1 + places
            if total_digits > 4000:
                raise ValueError("Output exceeds 4000 digits")
            frac_part = Y_mag_str.zfill(places)
            res = ('-' if sign == -1 else '') + '0.' + frac_part
            return res
        else:
            total_digits = len_Y
            if total_digits > 4000:
                raise ValueError("Output exceeds 4000 digits")
            split = len_Y - places
            int_part = Y_mag_str[:split]
            frac_part = Y_mag_str[split:]
            res = ('-' if sign == -1 else '') + int_part + '.' + frac_part
            return res

def _increment(s):
    digits = list(s)
    i = len(digits) - 1
    while i >= 0:
        if digits[i] == '9':
            digits[i] = '0'
            i -= 1
        else:
            digits[i] = str(int(digits[i]) + 1)
            return ''.join(digits)
    return '1' + ''.join(digits)

def round_dec(s, places, mode):
    if not isinstance(places, int) or isinstance(places, bool):
        raise ValueError("places must be an integer")
    if mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("Invalid mode")

    # Parse sign
    neg = False
    if s.startswith('-'):
        neg = True
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]

    # Split mantissa and exponent
    if 'e' in s or 'E' in s:
        mantissa_str, exp_str = s.split('e' if 'e' in s else 'E')
        exp_val = int(exp_str)
    else:
        mantissa_str = s
        exp_val = 0

    # Split integer and fractional parts
    if '.' in mantissa_str:
        int_part, frac_part = mantissa_str.split('.')
        dot_pos = len(int_part)
    else:
        int_part = mantissa_str
        frac_part = ''
        dot_pos = len(int_part)

    digits_str = int_part + frac_part
    digits_str = digits_str.lstrip('0')
    if not digits_str:
        digits_str = '0'

    shift = exp_val - len(frac_part)
    D = int(digits_str)

    K = shift + places

    # Check size limit early to avoid huge allocations
    # Total digits in result approx: len(digits_str) + max(0, K) + max(0, -places)
    # But careful: if rounded to 0, it's 1 digit.
    est_digits = len(digits_str) + max(0, K) + max(0, -places)
    if est_digits > 4005:
        raise ValueError("Output exceeds 4000 digits")

    if K >= 0:
        rounded_D = D * (10 ** K)
    else:
        Q = -K
        if Q > len(digits_str):
            A = 0
            R_str = digits_str
            A_str = '0'
        else:
            A_str = digits_str[:-Q] if Q > 0 else digits_str
            R_str = digits_str[-Q:]
            A = int(A_str) if A_str else 0
            R_str = R_str

        half_str = '5' + '0' * (Q - 1)

        if R_str < half_str:
            round_up = False
        elif R_str > half_str:
            round_up = True
        else: # Tie
            if mode == 'half_even':
                last_digit = int(A_str[-1]) if A_str else 0
                round_up = (last_digit % 2 != 0)
            elif mode in ('half_up', 'ceil', 'up'):
                round_up = True
            else: # half_down, floor, down
                round_up = False

        rounded_D = A + (1 if round_up else 0)

    if neg:
        rounded_D = -rounded_D

    num_str = str(abs(rounded_D))

    if places >= 0:
        if len(num_str) <= places:
            int_part = '0'
            frac_part = num_str.zfill(places)
        else:
            int_part = num_str[:-places]
            frac_part = num_str[-places:]
        result = f"{int_part}.{frac_part}"
    else:
        result = num_str + '0' * (-places)
        if rounded_D == 0:
            result = '0'

    # Final size check
    if len(result.replace('.', '')) > 4000:
        raise ValueError("Output exceeds 4000 digits")

    return result

def round_dec(s, places, mode):
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if not isinstance(places, int) or isinstance(places, bool):
        raise ValueError("places must be an int")
    if not isinstance(mode, str) or mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("invalid mode")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")

    s = s.strip()
    if not s:
        raise ValueError("empty string")

    sign = 1
    if s[0] in '+-':
        sign = 1 if s[0] == '+' else -1
        s = s[1:]
    if not s:
        raise ValueError("no digits")

    e_idx = -1
    for i, c in enumerate(s):
        if c in 'eE':
            e_idx = i
            break
    if e_idx != -1:
        mantissa = s[:e_idx]
        exp_str = s[e_idx+1:]
        if not exp_str:
            raise ValueError("invalid exponent")
        exp = int(exp_str)
    else:
        mantissa = s
        exp = 0

    dot_idx = mantissa.find('.')
    if dot_idx != -1:
        int_part = mantissa[:dot_idx]
        frac_part = mantissa[dot_idx+1:]
    else:
        int_part = mantissa
        frac_part = ""

    if not int_part and not frac_part:
        raise ValueError("no digits in mantissa")

    combined = (int_part + frac_part).lstrip('0') or '0'
    N = int(combined)
    E = exp - len(frac_part)

    shift = E + places

    if shift >= 0:
        R = sign * N * (10 ** shift)
    else:
        D = 10 ** (-shift)
        quotient, remainder = divmod(N, D)

        is_tie = (2 * remainder == D)
        f_gt_half = (2 * remainder > D)

        def round_pos(q, r, d, m):
            if m in ("floor", "down"):
                return q
            if m in ("ceil", "up"):
                return q + (1 if r > 0 else 0)
            if m == "half_down":
                return q + (1 if f_gt_half else 0)
            if m == "half_up":
                return q + (1 if f_gt_half or is_tie else 0)
            if m == "half_even":
                if f_gt_half:
                    return q + 1
                if is_tie:
                    return q + (1 if q % 2 else 0)
                return q
            return q

        adj_mode = mode
        if sign == -1:
            if mode in ("floor", "up"):
                adj_mode = "ceil"
            elif mode in ("ceil", "down"):
                adj_mode = "floor"
            # half_* remain same

        R_pos = round_pos(quotient, remainder, D, adj_mode)
        R = sign * R_pos

    if R == 0:
        if places > 0:
            return "0." + "0" * places
        else:
            return "0"

    abs_R = abs(R)
    sign_str = "-" if R < 0 else ""

    if places > 0:
        int_part = abs_R // (10 ** places)
        frac_part = abs_R % (10 ** places)
        int_str = str(int_part) if int_part > 0 else "0"
        frac_str = str(frac_part).zfill(places)
        res = sign_str + int_str + "." + frac_str
        if len(res.replace(".", "")) > 4000:
            raise ValueError("output exceeds 4000 digits")
    else:
        trailing = -places
        res = sign_str + str(abs_R) + "0" * trailing
        if len(res) > 4000:
            raise ValueError("output exceeds 4000 digits")

    return res

