def round_dec(s, places, mode):
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if isinstance(places, bool) or not isinstance(places, int):
        raise ValueError("places must be an int")
    if not isinstance(mode, str) or mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("Invalid mode")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")

    # Parse exponent
    ei = -1
    for i, c in enumerate(s):
        if c in 'eE':
            if ei != -1: raise ValueError("Invalid s")
            ei = i
    if ei != -1:
        exp_str = s[ei+1:]
        digits_part = exp_str.lstrip('+-')
        if not digits_part.isdigit() or not (1 <= len(digits_part) <= 10):
            raise ValueError("Invalid exponent")
        exp = int(exp_str)
        m_str = s[:ei]
    else:
        exp = 0
        m_str = s

    # Parse mantissa
    dot_idx = m_str.find('.')
    if m_str.count('.') > 1:
        raise ValueError("Invalid s")
    if dot_idx != -1:
        int_p = m_str[:dot_idx]
        frac_p = m_str[dot_idx+1:]
    else:
        int_p = m_str
        frac_p = ""

    if not int_p and not frac_p:
        raise ValueError("At least one digit required")
    if int_p and not int_p.isdigit():
        raise ValueError("Invalid digits")
    if frac_p and not frac_p.isdigit():
        raise ValueError("Invalid digits")

    # Extract sign and digits
    sign = 1
    digits = int_p + frac_p
    if digits.startswith('+'):
        digits = digits[1:]
    elif digits.startswith('-'):
        sign = -1
        digits = digits[1:]
    if not digits or not digits.isdigit():
        raise ValueError("At least one digit required")

    M = int(digits)
    M_len = len(digits.lstrip('0') or '0')
    E = exp - len(frac_p)
    P = places

    # Rounding logic
    exp_shift = E + P
    if exp_shift >= 0:
        R = M * (10 ** exp_shift)
    else:
        k = -exp_shift
        if k == 0:
            R = M
        elif k >= M_len + 2:
            R = 0 if M == 0 else 1  # M < 10^k, rounds to 0 or 1 depending on mode? Actually M/10^k < 1, so 0.
            # Wait, if M > 0 and M < 10^k, then M/10^k is in (0, 1).
            # Rounding to nearest integer: 0.
            R = 0
        else:
            divisor = 10**k
            q, r = divmod(M, divisor)
            if r == 0:
                R = q
            else:
                half = divisor // 2
                if r < half:
                    R = q
                elif r > half:
                    R = q + 1
                else: # tie
                    if mode == "half_even":
                        R = q + (q & 1)
                    elif mode == "half_up":
                        R = q + 1
                    elif mode == "half_down":
                        R = q
                    elif mode in ("floor", "down"):
                        R = q
                    else: # ceil, up
                        R = q + 1

    # Size check
    if P <= 0:
        out_digits = len(str(R)) + (-P)
    else:
        out_digits = len(str(R // (10**P))) + P
    if out_digits > 4000:
        raise ValueError("Output exceeds 4000 digits")

    # Format output
    if P <= 0:
        val = R * (10 ** (-P))
        s_out = str(val)
        if sign == -1 and val != 0:
            s_out = "-" + s_out
    else:
        div = 10**P
        int_part = R // div
        frac_part = R % div
        s_int = str(int_part)
        s_frac = str(frac_part).zfill(P)
        s_out = s_int + "." + s_frac
        if sign == -1 and (int_part != 0 or frac_part != 0):
            s_out = "-" + s_out

    return s_out
